}


const InspirationDynamicPage = async ({ params }: { params: Promise<{ slug: string }> }) => {
  const { slug } = await params;
  const pageData = getPageData(slug);

  if (!pageData || !pageData.components) {
    notFound();
  }

  return (
    <main>
      <PageBuilder components={pageData.components} />
    </main>
  );
};

export default InspirationDynamicPage;

"use client";
import Image from "next/image";
import React, { useState, useCallback, useEffect } from "react";
import { useRouter } from "next/navigation";
import styles from "./ProductHero.module.css";
import { FrontendProduct, getProductVariants, getProductVariantsByNameFallback } from "@/lib/products";
import { getColors, BackendColor } from "@/lib/colors";

interface ProductHeroProps {
  product: FrontendProduct;
}

// --- ICONS ---
const CloseIcon = ({ size = 24, color = "#333" }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M18 6L6 18" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    <path d="M6 6L18 18" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

const CheckmarkIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M20 6L9 17L4 12" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
