            <button
              type="button"
              style={{ width: '100%', textAlign: 'left', background: 'none', border: 'none', cursor: 'pointer', padding: '8px 12px', fontSize: 14, fontWeight: 500 }}
              className={selectedRoomId === null ? styles.sortOption : ''}
              data-selected={selectedRoomId === null ? 'true' : undefined}
              onClick={() => { onSelect(null); setIsOpen(false); }}
            >
              Hamısı
            </button>
          </li>
          {rooms.length > 0 ? (
            rooms.map((r) => (
              <li key={r.id}>
                <button
                  type="button"
                  style={{ width: '100%', textAlign: 'left', background: 'none', border: 'none', cursor: 'pointer', padding: '8px 12px', fontSize: 14, fontWeight: 500 }}
                  className={selectedRoomId === r.id ? styles.sortOption : ''}
                  data-selected={selectedRoomId === r.id ? 'true' : undefined}
                  onClick={() => { onSelect(r.id); setIsOpen(false); }}
                >
                  {r.name}
                </button>
              </li>
            ))
          ) : (
            <li style={{ padding: '10px', color: '#999' }}>Yüklənir...</li>
          )}
        </ul>
      </div>
    </div>
  );
};

const ColourDropdown = ({ colors, selectedName, onSelect }: { colors: BackendColor[]; selectedName: string; onSelect: (name: string) => void }) => {
  const [isOpen, setIsOpen] = useState(false);
  const displayLabel = selectedName ? `Colour - ${selectedName}` : 'Colour';
  return (
    <div className={styles.dropdown}>
      <button type="button" className={styles.dropdownButton} onClick={() => setIsOpen(!isOpen)}>
        <span>{displayLabel}</span>
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" className={`${styles.arrow} ${isOpen ? styles.arrowOpen : ''}`}>
          <path d="M6 9L12 15L18 9" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </button>
      <div className={`${styles.dropdownMenu} ${isOpen ? styles.menuOpen : ''}`}>
        <div className={styles.colorSwatches}>
          {colors.length > 0 ? (
            colors.map((c) => (
              <button
                key={c.id}
                type="button"
                className={`${styles.colorSwatch} ${selectedName === c.name ? styles.colorSwatchSelected : ''}`}
                style={{ background: c.hexCode || '#ccc' }}
                title={c.name}
                onClick={() => { onSelect(c.name); setIsOpen(false); }}
              />
            ))
          ) : (
            <span className={styles.colorSwatchLoading}>Yüklənir...</span>
          )}
        </div>
      </div>
    </div>
  );
};

type SortOption = { label: string; value: string };
const SortDropdown = ({
  options,
  value,
  onChange,
}: {
  options: readonly SortOption[];
  value: string;
  onChange: (value: string) => void;
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const current = options.find((o) => o.value === value) || options[0];
  return (
    <div className={styles.dropdown}>
      <button
        type="button"
        className={styles.dropdownButton}
        onClick={() => setIsOpen(!isOpen)}
      >
        <span>{current?.label ?? 'Sırala'}</span>
        <svg
          width="12"
          height="12"
          viewBox="0 0 24 24"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          className={`${styles.arrow} ${isOpen ? styles.arrowOpen : ''}`}
        >
          <path d="M6 9L12 15L18 9" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </button>
      <div className={`${styles.dropdownMenu} ${isOpen ? styles.menuOpen : ''}`}>
        <ul>
          {options.map((opt) => (
            <li key={opt.value}>
              <button
                type="button"
                data-selected={opt.value === value ? 'true' : undefined}
                className={styles.sortOption}
                style={{ width: '100%', textAlign: 'left', background: 'none', border: 'none', cursor: 'pointer', padding: '8px 12px', fontSize: 14, fontWeight: 500 }}
                onClick={() => {
                  onChange(opt.value);
                  setIsOpen(false);
                }}
              >
                {opt.label}
              </button>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

interface DropdownFiltersProps {
  onColorSelect?: (colorName: string) => void;
  selectedColor?: string;
  colors?: BackendColor[];
  materials?: Material[];
  selectedMaterialId?: number | null;
  onMaterialSelect?: (id: number | null) => void;
  selectedDepthRange?: DepthRange;
  onDepthRangeSelect?: (range: DepthRange) => void;
  collections?: BackendCollection[];
  selectedCollectionId?: number | null;
  onCollectionSelect?: (id: number | null) => void;
  rooms?: Room[];
  selectedRoomId?: number | null;
  onRoomSelect?: (id: number | null) => void;
  sortBy?: string;
  onSortChange?: (sortBy: string) => void;
}

const DropdownFilters = ({
  onColorSelect,
  selectedColor = '',
  colors = [],
  materials = [],
  selectedMaterialId = null,
  onMaterialSelect,
  selectedDepthRange = null,
  onDepthRangeSelect,
  collections = [],
  selectedCollectionId = null,
  onCollectionSelect,
  rooms = [],
  selectedRoomId = null,
  onRoomSelect,
  sortBy = 'newest',
  onSortChange,
}: DropdownFiltersProps) => {
  const [isMobileFilterOpen, setIsMobileFilterOpen] = useState(false);
  const [colourOptions, setColourOptions] = useState<BackendColor[]>(colors);

  const [selectedFilters, setSelectedFilters] = useState<{
    material: number | null;
    depth: DepthRange;
    colour: string;
    collection: number | null;
    room: number | null;
  }>({
    material: selectedMaterialId,
    depth: selectedDepthRange,
    colour: selectedColor,
    collection: selectedCollectionId,
    room: selectedRoomId
  });
  const [openSections, setOpenSections] = useState({
    material: false,
    depth: false,
    colour: false,
    collection: false,
    room: false
  });

  // Xarici rənglər dəyişəndə yenilə
  useEffect(() => {
    setColourOptions(colors);
  }, [colors]);

  // Xarici selectedColor dəyişəndə yenilə
  useEffect(() => {
    setSelectedFilters(prev => ({
      ...prev,
      colour: selectedColor
    }));
  }, [selectedColor]);

  useEffect(() => {
    setSelectedFilters((prev) => ({ ...prev, collection: selectedCollectionId }));
  }, [selectedCollectionId]);

  useEffect(() => {
    setSelectedFilters((prev) => ({ ...prev, room: selectedRoomId }));
  }, [selectedRoomId]);

  useEffect(() => {
    setSelectedFilters((prev) => ({ ...prev, depth: selectedDepthRange }));
  }, [selectedDepthRange]);

  useEffect(() => {
    setSelectedFilters((prev) => ({ ...prev, material: selectedMaterialId }));
  }, [selectedMaterialId]);

  // Backend sortBy: newest | price_asc | price_desc | name_asc | name_desc
  const SORT_OPTIONS = [
    { label: 'Ən yenilərə görə', value: 'newest' },
    { label: 'A-dan Z-yə', value: 'name_asc' },
    { label: 'Z-dən A-ya', value: 'name_desc' },
    { label: 'Ucuzdan Bahaya', value: 'price_asc' },
    { label: 'Bahadan Ucuza', value: 'price_desc' },
  ] as const;

  const isSameDepth = (a: DepthRange, b: DepthRange) => {
    if (a === null && b === null) return true;
    if (a === null || b === null) return false;
    return a.min === b.min && a.max === b.max;
  };

  const handleFilterSelect = (category: keyof typeof selectedFilters, value: string | number | DepthRange) => {
    const isDepth = category === 'depth';
    const isRoom = category === 'room';
    const isMaterial = category === 'material';
    const isCollection = category === 'collection';
    const current = selectedFilters[category];
    const same = isDepth ? isSameDepth(current as DepthRange, value as DepthRange) : current === value;
    const newValue = same ? (isMaterial || isCollection || isRoom ? null : isDepth ? null : '') : value;
    setSelectedFilters(prev => ({ ...prev, [category]: newValue }));
    if (category === 'colour' && onColorSelect && typeof value === 'string') {
      onColorSelect(value);
    }
    if (category === 'material' && onMaterialSelect) {
      onMaterialSelect(typeof newValue === 'number' ? newValue : null);
    }
    if (category === 'depth' && onDepthRangeSelect) {
      onDepthRangeSelect(newValue as DepthRange);
    }
    if (category === 'collection' && onCollectionSelect) {
      onCollectionSelect(typeof newValue === 'number' ? newValue : null);
    }
    if (category === 'room' && onRoomSelect) {
      onRoomSelect(typeof newValue === 'number' ? newValue : null);
    }
  };

  const toggleSection = (section: keyof typeof openSections) => {
    setOpenSections(prev => ({
      ...prev,
      [section]: !prev[section]
    }));
  };

  const handleApply = () => {
    setIsMobileFilterOpen(false);
  };

  const handleCancel = () => {
    setIsMobileFilterOpen(false);
  };

  return (
    <div className={styles.filtersWrapper}>
      <div className={styles.leftFilters}>
        <MaterialDropdown
          materials={materials}
          selectedMaterialId={selectedMaterialId ?? null}
          onSelect={(id) => onMaterialSelect?.(id)}
        />
        <DepthDropdown
          selectedDepthRange={selectedDepthRange ?? null}
          onSelect={(range) => onDepthRangeSelect?.(range)}
        />
        <ColourDropdown colors={colourOptions} selectedName={selectedFilters.colour} onSelect={(name) => handleFilterSelect('colour', name)} />
        <CollectionDropdown
          collections={collections}
          selectedCollectionId={selectedCollectionId ?? null}
          onSelect={(id) => onCollectionSelect?.(id)}
        />
        <RoomDropdown
          rooms={rooms}
          selectedRoomId={selectedRoomId ?? null}
          onSelect={(id) => onRoomSelect?.(id)}
        />
      </div>

      <div className={styles.rightFilters}>
        <button
          className={styles.mobileFilterButton}
          onClick={() => setIsMobileFilterOpen(!isMobileFilterOpen)}
        >
          <div className={styles.filterIcon}>
            <span></span>
            <span></span>
            <span></span>
          </div>
          Filter
        </button>

        <span className={styles.itemsCount}>14 items</span>

        <div className={`${styles.mobileDropdownMenu} ${isMobileFilterOpen ? styles.open : ''}`}>
          <div className={styles.mobileDropdownContent}>
            <div className={styles.mobileDropdownHeader}>
              <h3>Filters</h3>
              <button className={styles.closeButton} onClick={handleCancel}>×</button>
            </div>

            <div className={styles.mobileFilterSection}>
              <h4
                className={openSections.material ? styles.open : ''}
                onClick={() => toggleSection('material')}
              >
                Material
                <span className={styles.arrow}>▼</span>
              </h4>
              <div className={`${styles.mobileFilterOptions} ${openSections.material ? styles.open : ''}`}>
                <div
                  className={`${styles.mobileFilterOption} ${selectedFilters.material === null ? styles.selected : ''}`}
                  onClick={() => handleFilterSelect('material', null)}
                >
                  Hamısı
                </div>
                {materials.length > 0 ? (
                  materials.map((m) => (
                    <div
                      key={m.id}
                      className={`${styles.mobileFilterOption} ${selectedFilters.material === m.id ? styles.selected : ''}`}
                      onClick={() => handleFilterSelect('material', m.id)}
                    >
                      {m.name}
                    </div>
                  ))
                ) : (
                  <div style={{ padding: '10px', color: '#999' }}>Yüklənir...</div>
                )}
              </div>
            </div>

            <div className={styles.mobileFilterSection}>
              <h4
                className={openSections.depth ? styles.open : ''}
                onClick={() => toggleSection('depth')}
              >
                Dərinlik
                <span className={styles.arrow}>▼</span>
              </h4>
              <div className={`${styles.mobileFilterOptions} ${openSections.depth ? styles.open : ''}`}>
                {DEPTH_RANGE_OPTIONS.map((opt) => (
                  <div
                    key={opt.label}
                    className={`${styles.mobileFilterOption} ${(opt.value === null && selectedFilters.depth === null) ||
                      (opt.value !== null && selectedFilters.depth !== null && opt.value?.min === selectedFilters.depth?.min && opt.value?.max === selectedFilters.depth?.max)
                      ? styles.selected
                      : ''
                      }`}
                    onClick={() => handleFilterSelect('depth', opt.value)}
                  >
                    {opt.label}
                  </div>
                ))}
              </div>
            </div>

            {/* MOBİL RƏNG FİLTRİ (API-dən) */}
            <div className={styles.mobileFilterSection}>
              <h4
                className={openSections.colour ? styles.open : ''}
                onClick={() => toggleSection('colour')}
              >
                Colour
                <span className={styles.arrow}>▼</span>
              </h4>
              <div className={`${styles.mobileFilterOptions} ${openSections.colour ? styles.open : ''}`}>
                {colourOptions.length > 0 ? (
                  <div className={styles.colorSwatches}>
                    {colourOptions.map((c) => (
                      <button
                        key={c.id}
                        type="button"
                        className={`${styles.colorSwatch} ${selectedFilters.colour === c.name ? styles.colorSwatchSelected : ''}`}
                        style={{ background: c.hexCode || '#ccc' }}
                        title={c.name}
                        onClick={() => handleFilterSelect('colour', c.name)}
                      />
                    ))}
                  </div>
                ) : (
                  <div style={{ padding: '10px' }}>Yüklənir...</div>
                )}
              </div>
            </div>

            <div className={styles.mobileFilterSection}>
              <h4
                className={openSections.collection ? styles.open : ''}
                onClick={() => toggleSection('collection')}
              >
                Kolleksiya
                <span className={styles.arrow}>▼</span>
              </h4>
              <div className={`${styles.mobileFilterOptions} ${openSections.collection ? styles.open : ''}`}>
                <div
                  className={`${styles.mobileFilterOption} ${selectedFilters.collection === null ? styles.selected : ''}`}
                  onClick={() => handleFilterSelect('collection', null)}
                >
                  Hamısı
                </div>
                {collections.length > 0 ? (
                  collections.map((c) => (
                    <div
                      key={c.id}
                      className={`${styles.mobileFilterOption} ${selectedFilters.collection === c.id ? styles.selected : ''}`}
                      onClick={() => handleFilterSelect('collection', c.id)}
                    >
                      {c.name}
                    </div>
                  ))
                ) : (
                  <div style={{ padding: '10px', color: '#999' }}>Yüklənir...</div>
                )}
              </div>
            </div>

            {/* Otaqlar üçün */}
            <div className={styles.mobileFilterSection}>
              <h4
                className={openSections.room ? styles.open : ''}
                onClick={() => toggleSection('room')}
              >
                Otaqlar
                <span className={styles.arrow}>▼</span>
              </h4>
              <div className={`${styles.mobileFilterOptions} ${openSections.room ? styles.open : ''}`}>
                <div
                  className={`${styles.mobileFilterOption} ${selectedFilters.room === null ? styles.selected : ''}`}
                  onClick={() => handleFilterSelect('room', null)}
                >
                  Hamısı
                </div>
                {rooms.length > 0 ? (
                  rooms.map((r) => (
                    <div
                      key={r.id}
                      className={`${styles.mobileFilterOption} ${selectedFilters.room === r.id ? styles.selected : ''}`}
                      onClick={() => handleFilterSelect('room', r.id)}
                    >
                      {r.name}
                    </div>
                  ))
                ) : (
                  <div style={{ padding: '10px', color: '#999' }}>Yüklənir...</div>
                )}
              </div>
            </div>

            <div className={styles.mobileFilterButtons}>
              <button className={styles.cancelButton} onClick={handleCancel}>
                Cancel
              </button>
              <button className={styles.applyButton} onClick={handleApply}>
                Apply
              </button>
            </div>
          </div>
        </div>

        {/* Sıralama dropdown — backend sortBy: newest | price_asc | price_desc | name_asc | name_desc */}
        <SortDropdown
          options={SORT_OPTIONS}
          value={sortBy}
          onChange={(value) => onSortChange?.(value)}
        />
      </div>
    </div>
  );
};

export default DropdownFilters;

'use client';

import React, { useState, useEffect, useRef, Suspense, useTransition } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import ProductHero from '../ProductHero/ProductHero';
import CategoryFilters from '../CategoryFilters/CategoryFilters';
import DropdownFilters from '../DropdownFilters/DropdownFilters';
import ProductGrid from '../ProductGrid/ProductGrid';
import ProductAbout from '../ProductAbout/ProductAbout';
import { getProducts, type FrontendProduct } from '@/lib/products';
import { type BackendColor } from '@/lib/colors';
import { type Material } from '@/lib/materials';
import { type BackendCollection } from '@/lib/collections';
import { type Room } from '@/lib/rooms';
import { type Category } from '@/lib/categories';
import styles from '../../page.module.css';

interface ClientProductPageProps {
  initialProducts: FrontendProduct[];
  initialColors: BackendColor[];
  initialMaterials: Material[];
  initialCollections: BackendCollection[];
  initialRooms: Room[];
  initialCategories: Category[];
}

function ProductGridSkeleton() {
  return (
    <div className={styles.loaderContainer}>
      <div className={styles.spinner}></div>
    </div>
  );
}

const ProductPageContent = ({ 
  initialProducts, 
  initialColors, 
  initialMaterials, 
  initialCollections, 
  initialRooms, 
  initialCategories 
}: ClientProductPageProps) => {
  const searchParams = useSearchParams();
  const searchFromUrl = searchParams.get('search')?.trim() || null;

  const [selectedRoomId, setSelectedRoomId] = useState<number | null>(() => {
    const v = searchParams.get('roomsId');
    return v ? parseInt(v, 10) || null : null;
  });

  const [selectedCategoryId, setSelectedCategoryId] = useState<number | null>(() => {
    const v = searchParams.get('CategoryId');
    return v ? parseInt(v, 10) || null : null;
  });

  const [selectedCollectionId, setSelectedCollectionId] = useState<number | null>(() => {
    const v = searchParams.get('collectionId');
    return v ? parseInt(v, 10) || null : null;
  });

  // Digər filtrlər
  const [selectedMaterialId, setSelectedMaterialId] = useState<number | null>(null);
  const [selectedDepthRange, setSelectedDepthRange] = useState<{ min: number; max?: number } | null>(null);
  const [selectedColor, setSelectedColor] = useState<string>('');
  const [sortBy, setSortBy] = useState<string>('newest');

  const router = useRouter();
  const [isPending, startTransition] = useTransition();

  const updateUrlParams = (updates: Record<string, string | null>) => {
    startTransition(() => {
      const url = new window.URL(window.location.href);
      Object.entries(updates).forEach(([key, val]) => {
        if (val === null || val === '') url.searchParams.delete(key);
        else url.searchParams.set(key, val);
      });
      router.push(url.pathname + url.search, { scroll: false });
    });
  };

  // SSR-dən gələn datalarla initialize edirik (LOADING OLMUR)
  const [allProducts, setAllProducts] = useState<FrontendProduct[]>(initialProducts);
  const [displayedProducts, setDisplayedProducts] = useState<FrontendProduct[]>(initialProducts);
  const [loadingMore, setLoadingMore] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  
  const productsPerPage = 12;
  const [hasMore, setHasMore] = useState(initialProducts.length >= productsPerPage);

  // URL-dən yeni data gələndə (Server Component təzələnəndə) siyahını sıfırla
  useEffect(() => {
    setAllProducts(initialProducts);
    setDisplayedProducts(initialProducts);
    setCurrentPage(1);
    setHasMore(initialProducts.length >= productsPerPage);
  }, [initialProducts]);

  // Daha çox məhsul yüklə
  const loadMoreProducts = async () => {
    if (loadingMore || !hasMore) return;

    try {
      setLoadingMore(true);
      const nextPage = currentPage + 1;
      
      const selectedColorObj = initialColors.find(c => c.name === selectedColor);
      const selectedColorId = selectedColorObj ? selectedColorObj.id : null;

      const newProducts = await getProducts({
        pageNumber: nextPage,
        pageSize: productsPerPage,
        sortBy,
        ...(searchFromUrl && { searchTerm: searchFromUrl }),
        ...(selectedCategoryId != null && { categoryId: selectedCategoryId }),
        ...(selectedRoomId != null && { roomId: selectedRoomId }),
        ...(selectedMaterialId != null && { materialIds: [selectedMaterialId] }),
        ...(selectedDepthRange != null && {
          minDepth: selectedDepthRange.min,
          ...(selectedDepthRange.max != null && { maxDepth: selectedDepthRange.max }),
        }),
        ...(selectedCollectionId != null && { collectionId: selectedCollectionId }),
        ...(selectedColorId != null && { colorIds: [selectedColorId] }),
      });

      if (newProducts.length === 0) {
        setHasMore(false);
        return;
      }

      const updatedProducts = [...allProducts, ...newProducts];
      setAllProducts(updatedProducts);
      setDisplayedProducts(updatedProducts);
      setCurrentPage(nextPage);

      if (newProducts.length < productsPerPage) {
        setHasMore(false);
      }
    } catch (error) {
      console.error('Daha çox məhsul yüklənmədi:', error);
    } finally {
      setLoadingMore(false);
    }
  };

  const handleColorSelect = (colorName: string) => {
    const newColor = selectedColor === colorName ? '' : colorName;
    setSelectedColor(newColor);
    const colorObj = initialColors.find(c => c.name === newColor);
    updateUrlParams({ colorId: colorObj ? String(colorObj.id) : null });
  };

  const handleCategoryChange = (id: number | null) => {
    setSelectedCategoryId(id);
    updateUrlParams({ CategoryId: id ? String(id) : null });
  };

  const handleMaterialSelect = (id: number | null) => {
    setSelectedMaterialId(id);
    updateUrlParams({ materialId: id ? String(id) : null });
  };

  const handleCollectionSelect = (id: number | null) => {
    setSelectedCollectionId(id);
    updateUrlParams({ collectionId: id ? String(id) : null });
  };

  const handleRoomSelect = (id: number | null) => {
    setSelectedRoomId(id);
    updateUrlParams({ roomsId: id ? String(id) : null });
  };

  const handleDepthSelect = (range: {min: number, max?: number} | null) => {
    setSelectedDepthRange(range);
    updateUrlParams({ 
        minDepth: range ? String(range.min) : null,
        maxDepth: range?.max ? String(range.max) : null
    });
  };

  const handleSortChange = (sort: string) => {
    setSortBy(sort);
    updateUrlParams({ sortBy: sort });
  };

  const heroTitle = selectedCategoryId == null
    ? 'All Products'
    : (initialCategories.find((c) => c.id === selectedCategoryId)?.name ?? 'All Products');

  return (
    <main>
      <ProductHero title={heroTitle} />
      <CategoryFilters
        selectedCategoryId={selectedCategoryId}
        onCategoryChange={handleCategoryChange}
      />
      <DropdownFilters
        onColorSelect={handleColorSelect}
        selectedColor={selectedColor}
        colors={initialColors}
        materials={initialMaterials}
        selectedMaterialId={selectedMaterialId}
        onMaterialSelect={handleMaterialSelect}
        selectedDepthRange={selectedDepthRange}
        onDepthRangeSelect={handleDepthSelect}
        collections={initialCollections}
        selectedCollectionId={selectedCollectionId}
        onCollectionSelect={handleCollectionSelect}
        rooms={initialRooms}
        selectedRoomId={selectedRoomId}
        onRoomSelect={handleRoomSelect}
        sortBy={sortBy}
        onSortChange={handleSortChange}
      />
      {isPending ? (
        <ProductGridSkeleton />
      ) : (
        <ProductGrid
          products={displayedProducts}
          onLoadMore={loadMoreProducts}
          hasMore={hasMore}
          loadingMore={loadingMore}
        />
      )}
      <ProductAbout />
    </main>
  );
};

export default function ClientProductPage(props: ClientProductPageProps) {
  return (
    <Suspense fallback={<ProductGridSkeleton />}>
      <ProductPageContent {...props} />
    </Suspense>
  );
}

"use client";

import React from "react";
import styles from "./ProductGrid.module.css";
import ProductCard from "@/components/ProductCard/ProductCard";
import { FrontendProduct } from "@/lib/products";

interface ProductGridProps {
  products: FrontendProduct[];
  onLoadMore?: () => void;
  hasMore?: boolean;
  loadingMore?: boolean;
}

const ProductGrid = ({
  products,
  onLoadMore,
  hasMore = false,
  loadingMore = false,
}: ProductGridProps) => {
  const totalItems = products.length;
  const shownItems = products.length;

  if (!products || products.length === 0) {
    return (
      <div className={styles.gridContainer}>
        <div className={styles.noProducts}>
          Hələlik heç bir məhsul tapılmadı.
        </div>
      </div>
    );
  }

  return (
    <div className={styles.gridContainer}>
      <div className={styles.countDisplay}>Show {shownItems} items</div>

      <div className={styles.grid}>
        {products.map((product, index) => (
          <ProductCard
            key={product.id}
            id={product.id}
            title={product.title}
            color={product.color}
            measurements={product.measurements}
            position={product.position}
            price={product.price}
            imageSrc={product.imageSrc}
            imageSrcHover={product.imageSrcHover}
            priority={index < 8}
            createdAt={(product as any).createdAt}
            isNew={index < 6}
          />
        ))}
      </div>

      <div className={styles.paginationControls}>
        <p className={styles.itemCount}>
          Showing {shownItems} out of {totalItems} items
        </p>

        {hasMore && (
          <button
            className={styles.loadMoreButton}
            onClick={onLoadMore}
            disabled={loadingMore}
          >
            {loadingMore ? "Loading..." : "Load More"}
          </button>
        )}
      </div>
    </div>
  );
};

