'use client';

import React, { useState, useEffect } from 'react';
import Image from 'next/image';
import { useRouter, useParams } from 'next/navigation';
import Link from 'next/link';
import { getCategoryById, updateCategory, deleteCategory, getCategories, Category, uploadCategoryImage, deleteCategoryImage } from '@/lib/categories';
import { useAdminModal } from '@/context/admin-modal-context';
import styles from '../page.module.css';

import { FaSave, FaTags, FaLayerGroup, FaEdit, FaTrash, FaPlus, FaCloudUploadAlt, FaTimes } from 'react-icons/fa';

export default function EditCategoryPage() {
  const router = useRouter();
  const params = useParams();
  const id = params?.id as string;
  const { openModal } = useAdminModal();

  const [loading, setLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);

  // Form State
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [parentCategoryId, setParentCategoryId] = useState<number>(0);

  // Dropdown Data + Alt kateqoriyalar
  const [categories, setCategories] = useState<Category[]>([]);
  const [subCategories, setSubCategories] = useState<Category[]>([]);

  // Image
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  useEffect(() => {
    async function fetchData() {
      try {
        const token = localStorage.getItem('accessToken') || '';

        const allCats = await getCategories();
        setCategories(Array.isArray(allCats) ? allCats : []);

        if (id) {
          const data = await getCategoryById(id, token);
          if (data) {
            setName(data.name);
            setDescription(data.description || '');
            setParentCategoryId(data.parentCategoryId || 0);
            setImageUrl(data.imageUrl || null);
            const subs = Array.isArray(data.subCategories) && data.subCategories.length > 0
              ? data.subCategories
              : (Array.isArray(allCats) ? allCats.filter((c) => c.parentCategoryId === Number(id)) : []);
            setSubCategories(subs);
          }
        }
      } catch (err) {
        console.error(err);
      } finally {
        setInitialLoading(false);
      }
    }
    fetchData();
  }, [id]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const token = localStorage.getItem('accessToken') || '';

      if (imageFile) {
        await uploadCategoryImage(id, imageFile, token);
        const updated = await getCategoryById(id, token);
        setImageUrl(updated.imageUrl || null);
        setImageFile(null);
        setImagePreview(null);
      }

      const payload = {
        name: name,
        description: description,
        parentCategoryId: parentCategoryId === 0 ? null : parentCategoryId
      };
      await updateCategory(id, payload, token);

      openModal({
        type: 'success',
        title: 'Updated Successfully!',
        message: 'Category details have been saved.',
        confirmText: 'Back to List',
        onConfirm: () => router.push('/admin/categories')
      });
    } catch (error: any) {
      openModal({ type: 'error', title: 'Error', message: error.message || 'Failed to update' });
    } finally {
      setLoading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setImageFile(file);
      setImagePreview(URL.createObjectURL(file));
    }
  };

  const removeNewFile = () => {
    setImageFile(null);
    setImagePreview(null);
  };

  const handleImageDelete = () => {
    openModal({
      type: 'warning',
      title: 'Şəkli sil',
      message: 'Bu kateqoriyanın şəklini silmək istədiyinizə əminsiniz?',
      confirmText: 'Bəli, sil',
      cancelText: 'Ləğv et',
      onConfirm: async () => {
        setLoading(true);
        try {
          const token = localStorage.getItem('accessToken') || '';
          await deleteCategoryImage(id, token);
          setImageUrl(null);
        } catch (err: any) {
          openModal({ type: 'error', title: 'Xəta', message: err.message || 'Şəkil silinə bilmədi.' });
        } finally {
          setLoading(false);
        }
      }
    });
  };

  const handleDeleteSub = (subId: number, subName: string) => {
    openModal({
      type: 'warning',
      title: 'Kateqoriyanı sil',
      message: `"${subName}" silinsin? Bu geri alına bilməz.`,
      confirmText: 'Sil',
      cancelText: 'Ləğv et',
      onConfirm: async () => {
        const token = localStorage.getItem('accessToken') || '';
        await deleteCategory(subId, token);
        setSubCategories((prev) => prev.filter((c) => c.id !== subId));
      },
    });
  };

  if (initialLoading) return <div style={{ padding: 40, textAlign: 'center' }}>Loading...</div>;

  return (
    <form onSubmit={handleSubmit} className={styles.container}>
      <div className={styles.header}>
        <h1 className={styles.title}>Edit Category</h1>
        <div className={styles.headerActions}>
          <Link href="/admin/categories" className={styles.cancelBtn}>Cancel</Link>
          <button type="submit" className={styles.saveBtn} disabled={loading}>
            <FaSave /> {loading ? 'Saving...' : 'Save Changes'}
          </button>
        </div>
      </div>

      <div className={styles.formGrid}>

        {/* SOL: Məlumatlar */}
        <div className={styles.card}>
          <div className={styles.cardTitle}><FaTags /> Basic Information</div>
          <div className={styles.formGroup}>
            <label className={styles.label}>Name</label>
            <input type="text" className={styles.input} value={name} onChange={(e) => setName(e.target.value)} required />
          </div>
          <div className={styles.formGroup}>
            <label className={styles.label}>Description</label>
            <textarea className={styles.textarea} value={description} onChange={(e) => setDescription(e.target.value)} />
          </div>
        </div>

        {/* SAĞ: Təşkilat və Şəkil */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>

          {/* IMAGE CARD — eyni UI designers/collections ilə */}
          <div className={styles.card}>
            <div className={styles.cardTitle}><FaCloudUploadAlt /> Category Image</div>

            {imagePreview ? (
              <div className={styles.previewWrapper} style={{ position: 'relative' }}>
                <Image src={imagePreview} alt="New" fill className={styles.previewImage} sizes="300px" unoptimized />
                <button type="button" onClick={removeNewFile} className={styles.removeImageBtn} title="Cancel"><FaTimes /></button>
              </div>
            ) : (
              <>
                {imageUrl && (
                  <div className={styles.previewWrapper} style={{ marginBottom: 15, borderStyle: 'solid', position: 'relative' }}>
                    <Image src={imageUrl} alt="Current" fill className={styles.previewImage} sizes="300px" />
                    <span style={{ position: 'absolute', bottom: 5, left: 5, background: '#111', color: '#fff', fontSize: 10, padding: '2px 6px', borderRadius: 4 }}>Current</span>
                    <button type="button" onClick={handleImageDelete} className={styles.removeImageBtn} title="Remove image" style={{ background: 'rgba(239, 68, 68, 0.9)', color: '#fff' }}><FaTrash size={12} /></button>
                  </div>
                )}
                <label className={styles.uploadArea}>
                  <input type="file" accept="image/png,image/jpeg,image/jpg" hidden onChange={handleFileChange} />
                  <div style={{ fontSize: 28, color: '#ccc', marginBottom: 8 }}><FaCloudUploadAlt /></div>
                  <span style={{ fontSize: 13, color: '#666', fontWeight: 500 }}>
                    {imageUrl ? 'Change Image' : 'Upload Image'}
                  </span>
                </label>
              </>
            )}
          </div>

          <div className={styles.card}>
            <div className={styles.cardTitle}><FaLayerGroup /> Organization</div>

            <div className={styles.formGroup}>
              <label className={styles.label}>Parent Category</label>
              <select
                className={styles.input}
                value={parentCategoryId}
                onChange={(e) => setParentCategoryId(Number(e.target.value))}
              >
                <option value={0}>No Parent (Main Category)</option>
                {categories
                  .filter(cat => cat.id !== Number(id))
                  .map((cat) => (
                    <option key={cat.id} value={cat.id}>
                      {cat.name}
                    </option>
                  ))}
              </select>
            </div>

            <div className={styles.formGroup} style={{ marginTop: 24 }}>
              <label className={styles.label}>Alt kateqoriyalar</label>
              {subCategories.length > 0 ? (
                <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
                  {subCategories.map((sub) => (
                    <li
                      key={sub.id}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        padding: '10px 12px',
                        background: '#f9fafb',
                        borderRadius: 8,
                        marginBottom: 8,
                      }}
                    >
                      <span style={{ fontWeight: 500 }}>{sub.name}</span>
                      <span style={{ display: 'flex', gap: 8 }}>
                        <Link
                          href={`/admin/categories/${sub.id}`}
                          style={{
                            padding: '6px 10px',
                            background: '#111',
                            color: '#fff',
                            borderRadius: 6,
                            fontSize: 12,
                            textDecoration: 'none',
                            display: 'inline-flex',
                            alignItems: 'center',
                            gap: 4,
                          }}
                        >
                          <FaEdit size={12} /> Edit
                        </Link>
                        <button
                          type="button"
                          onClick={() => handleDeleteSub(sub.id, sub.name)}
                          style={{
                            padding: '6px 10px',
                            background: '#dc2626',
                            color: '#fff',
                            border: 'none',
                            borderRadius: 6,
                            fontSize: 12,
                            cursor: 'pointer',
                            display: 'inline-flex',
                            alignItems: 'center',
                            gap: 4,
                          }}
                        >
                          <FaTrash size={12} /> Sil
                        </button>
                      </span>
                    </li>
                  ))}
                </ul>
              ) : (
                <p style={{ fontSize: 13, color: '#666', marginBottom: 10 }}>Alt kateqoriya yoxdur.</p>
              )}
              <Link
                href={`/admin/categories/new?parentId=${id}`}
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 6,
                  marginTop: 4,
                  fontSize: 13,
                  color: '#111',
                  fontWeight: 600,
                }}
              >
                <FaPlus size={12} /> Yeni alt kateqoriya
              </Link>
            </div>
          </div>

        </div>
      </div>
    </form>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import Image from 'next/image';
import { useRouter, useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { createCategory, getCategories, Category, uploadCategoryImage } from '@/lib/categories';
import { useAdminModal } from '@/context/admin-modal-context';
import styles from '../page.module.css';

import { FaSave, FaTags, FaLayerGroup, FaCloudUploadAlt, FaTimes } from 'react-icons/fa';

export default function NewCategoryPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const parentIdFromUrl = searchParams.get('parentId');
  const { openModal } = useAdminModal();
  const [loading, setLoading] = useState(false);

  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [parentCategoryId, setParentCategoryId] = useState<number>(0);

  // Image
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [categories, setCategories] = useState<Category[]>([]);

  useEffect(() => {
    async function fetchCats() {
      try {
        const data = await getCategories();
        setCategories(Array.isArray(data) ? data : []);
      } catch (error) {
        console.error("Failed to fetch categories", error);
      }
    }
    fetchCats();
  }, []);

  useEffect(() => {
    if (parentIdFromUrl && categories.length > 0) {
      const pid = Number(parentIdFromUrl);
      if (pid && categories.some((c) => c.id === pid)) setParentCategoryId(pid);
    }
  }, [parentIdFromUrl, categories]);

  // SUBMIT
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) {
      openModal({ type: 'error', title: 'Error', message: 'Category Name is required!' });
      return;
    }

    setLoading(true);
    try {
      const token = localStorage.getItem('accessToken') || '';

      const payload = {
        name: name,
        description: description,
        // Əgər 0 seçilibsə null göndər, əks halda ID-ni göndər
        parentCategoryId: parentCategoryId === 0 ? null : parentCategoryId
      };

      const response = await createCategory(payload, token) as { id: number };
      const newCategoryId = response.id; // API creates category and returns it

      // Upload image if selected
      if (imageFile) {
        try {
          await uploadCategoryImage(newCategoryId, imageFile, token);
        } catch (imgError: any) {
          console.error("Image upload failed:", imgError);
          openModal({ type: 'warning', title: 'Kateqoriya Yaradıldı, Şəkil Yüklənmədi', message: 'Kateqoriya uğurla yaradıldı, lakin şəkli yükləmək mümkün olmadı. Zəhmət olmasa kateqoriyanı redaktə edərək şəkli yenidən yükləməyə cəhd edin.', onConfirm: () => router.push('/admin/categories') });
          return;
        }
      }

      openModal({
        type: 'success',
        title: 'Category Created!',
        message: 'New category has been added successfully.',
        confirmText: 'Go to Categories',
        onConfirm: () => router.push('/admin/categories')
      });

    } catch (error: any) {
      console.error(error);
      openModal({ type: 'error', title: 'Failed', message: error.message || 'Could not create category' });
    } finally {
      setLoading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setImageFile(file);
      setImagePreview(URL.createObjectURL(file));
    }
  };

  const removeNewFile = () => {
    setImageFile(null);
    setImagePreview(null);
  };

  return (
    <form onSubmit={handleSubmit} className={styles.container}>
      {/* Header */}
      <div className={styles.header}>
        <h1 className={styles.title}>New Category</h1>
        <div className={styles.headerActions}>
          <Link href="/admin/categories" className={styles.cancelBtn}>Cancel</Link>
          <button type="submit" className={styles.saveBtn} disabled={loading}>
            <FaSave /> {loading ? 'Saving...' : 'Save Category'}
          </button>
        </div>
      </div>

      <div className={styles.formGrid}>

        {/* SOL: Əsas Məlumatlar */}
        <div className={styles.card}>
          <div className={styles.cardTitle}><FaTags /> Basic Information</div>

          <div className={styles.formGroup}>
            <label className={styles.label}>Category Name</label>
            <input
              type="text" className={styles.input}
              value={name} onChange={(e) => setName(e.target.value)}
              placeholder="e.g. Living Room" required
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.label}>Description</label>
            <textarea
              className={styles.textarea}
              value={description} onChange={(e) => setDescription(e.target.value)}
              placeholder="Short description..."
            />
          </div>
        </div>

        {/* SAĞ: Təşkilat və Şəkil */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>

          {/* IMAGE CARD — eyni UI designers/collections ilə */}
          <div className={styles.card}>
            <div className={styles.cardTitle}><FaCloudUploadAlt /> Category Image</div>

            {imagePreview ? (
              <div className={styles.previewWrapper} style={{ position: 'relative' }}>
                <Image src={imagePreview} alt="Preview" fill className={styles.previewImage} sizes="300px" unoptimized />
                <button type="button" onClick={removeNewFile} className={styles.removeImageBtn} title="Remove"><FaTimes /></button>
              </div>
            ) : (
              <label className={styles.uploadArea}>
                <input type="file" accept="image/png,image/jpeg,image/jpg" hidden onChange={handleFileChange} />
                <div style={{ fontSize: 28, color: '#ccc', marginBottom: 8 }}><FaCloudUploadAlt /></div>
                <span style={{ fontSize: 13, color: '#666', fontWeight: 500 }}>Upload Image</span>
                <span style={{ fontSize: 12, color: '#999', marginTop: 4 }}>Image will be saved when you create the category.</span>
              </label>
            )}
          </div>

          <div className={styles.card}>
            <div className={styles.cardTitle}><FaLayerGroup /> Organization</div>

            <div className={styles.formGroup}>
              <label className={styles.label}>Parent Category</label>
              <select
                className={styles.input} // input stili ilə eyni olsun
                value={parentCategoryId}
                onChange={(e) => setParentCategoryId(Number(e.target.value))}
              >
                <option value={0}>No Parent (Main Category)</option>
                {categories.map((cat) => (
                  <option key={cat.id} value={cat.id}>
                    {cat.name}
                  </option>
                ))}
              </select>
              <p style={{ fontSize: 12, color: '#666', marginTop: 8 }}>
                Select "No Parent" if this is a main category.
              </p>
            </div>
          </div>

        </div>
      </div>
    </form>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { getCategories, deleteCategory, Category } from '@/lib/categories';
import { getCached, setCached } from '@/lib/admin-prefetch-cache';
import AdminTableSkeleton from '../components/AdminTableSkeleton';
import { AdminCheckbox } from '../components/AdminCheckbox';
import { useAdminModal } from '@/context/admin-modal-context';
import shared from '../components/admin-shared.module.css';
import styles from './page.module.css';
import { FaPlus, FaEdit, FaTrash, FaTags, FaBoxOpen, FaSearch } from 'react-icons/fa';

export default function AdminCategories() {
  const cached = getCached<Category[]>('categories');
  const [categories, setCategories] = useState<Category[]>(Array.isArray(cached) ? cached : []);
  const [loading, setLoading] = useState(!cached);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const { openModal } = useAdminModal();

  const fetchCategories = async (showLoader = true) => {
    try {
      if (showLoader) setLoading(true);
      const data = await getCategories();
      const list = Array.isArray(data) ? data : [];
      setCategories(list);
      setCached('categories', list);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCategories(!cached);
  }, []);

  // DELETE MODAL
  const handleDelete = (id: number) => {
    openModal({
      type: 'warning',
      title: 'Delete Category?',
      message: 'Are you sure you want to delete this category? This action cannot be undone.',
      confirmText: 'Yes, Delete',
      cancelText: 'Cancel',
      onConfirm: async () => {
        const token = localStorage.getItem('accessToken') || '';
        await deleteCategory(id, token);
        setCategories(prev => prev.filter(c => c.id !== id));
        setSelectedIds(prev => prev.filter(selectedId => selectedId !== id));
      }
    });
  };

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) setSelectedIds(categories.map(c => c.id));
    else setSelectedIds([]);
  };

  const handleSelectOne = (id: number) => {
    setSelectedIds(prev =>
      prev.includes(id) ? prev.filter(item => item !== id) : [...prev, id]
    );
  };

  const handleBulkDelete = () => {
    openModal({
      type: 'warning',
      title: 'Toplu Silinmə',
      message: `Seçilmiş ${selectedIds.length} kateqoriyanı silmək istədiyinizə əminsiniz? Bu geriyə alına bilməz.`,
      confirmText: 'Bəli, Sil',
      cancelText: 'Ləğv et',
      onConfirm: async () => {
        const token = localStorage.getItem('accessToken') || '';
        setLoading(true);
        try {
          const results = await Promise.allSettled(
            selectedIds.map(id => deleteCategory(id, token))
          );
          const successIds = results
            .map((r, idx) => r.status === 'fulfilled' ? selectedIds[idx] : null)
            .filter(Boolean) as number[];
          setCategories(prev => prev.filter(item => !successIds.includes(item.id)));
          setSelectedIds([]);
        } catch (error) {
          console.error("Toplu silinmə xətası", error);
        } finally {
          setLoading(false);
        }
      }
    });
  };

  return (
    <div className={shared.container}>
      <div className={shared.header}>
        <h1 className={shared.title}>Categories</h1>
        <div className={shared.headerActions}>
          {selectedIds.length > 0 && (
            <button onClick={handleBulkDelete} className={`${shared.addButton} ${shared.bulkDeleteBtn}`}>
              <FaTrash /> Seçilmişləri Sil ({selectedIds.length})
            </button>
          )}
          <Link href="/admin/categories/new" className={shared.addButton}>
            <FaPlus /> Add Category
          </Link>
        </div>
      </div>

      <div className={shared.filtersBar}>
        <div className={shared.searchWrapper}>
          <FaSearch className={shared.searchIcon} />
          <input
            type="text"
            placeholder="Search categories..."
            className={shared.searchInput}
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className={shared.tableCard}>
        {loading ? (
          <AdminTableSkeleton rows={8} />
        ) : categories.length === 0 ? (
          <div className={shared.emptyState}>
            <FaBoxOpen size={48} className={shared.emptyStateIcon} />
            <p>No categories found.</p>
          </div>
        ) : (
          (() => {
            const filtered = categories.filter(cat => 
              cat.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
              cat.description?.toLowerCase().includes(searchTerm.toLowerCase())
            );
            
            if (filtered.length === 0 && searchTerm) {
              return (
                <div className={shared.emptyState}>
                  <FaSearch size={48} className={shared.emptyStateIcon} />
                  <p>No categories match your search "{searchTerm}".</p>
                </div>
              );
            }

            return (
              <table className={shared.table}>
                <thead>
                  <tr>
                    <th>
                      <AdminCheckbox
                        checked={filtered.length > 0 && selectedIds.length === filtered.length}
                        onChange={(e) => {
                          if (e.target.checked) setSelectedIds(filtered.map(c => c.id));
                          else setSelectedIds([]);
                        }}
                        indeterminate={selectedIds.length > 0 && selectedIds.length < filtered.length}
                        aria-label="Hamısını seç"
                      />
                    </th>
                    <th>Category</th>
                    <th>Description</th>
                    <th style={{ textAlign: 'right' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((cat) => (
                    <tr key={cat.id} className={selectedIds.includes(cat.id) ? shared.selected : ''}>
                      <td>
                        <AdminCheckbox
                          checked={selectedIds.includes(cat.id)}
                          onChange={() => handleSelectOne(cat.id)}
                          aria-label={`Kateqoriya ${cat.name} seç`}
                        />
                      </td>
                      <td>
                        <div className={styles.cellContent}>
                          <div className={styles.imageWrapper}>
                            {cat.imageUrl ? (
                              <Image src={cat.imageUrl} alt={cat.name} width={48} height={48} className={styles.image} loading="lazy" />
                            ) : (
                              <div style={{width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#ccc'}}>
                                <FaTags />
                              </div>
                            )}
                          </div>
                          <div className={styles.nameInfo}>
                             <span className={styles.name}>{cat.name}</span>
                             <span className={styles.idBadge}>ID: #{cat.id}</span>
                          </div>
                        </div>
                      </td>
                      <td style={{color: '#666', maxWidth: 300}}>
                        {cat.description || '—'}
                      </td>
                      <td>
                        <div className={shared.actions}>
                          <Link href={`/admin/categories/${cat.id}`} className={`${shared.actionBtn} ${shared.editBtn}`} title="Edit">
                            <FaEdit />
                          </Link>
                          <button onClick={() => handleDelete(cat.id)} className={`${shared.actionBtn} ${shared.deleteBtn}`} title="Delete">
                            <FaTrash />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            );
          })()
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAdminModal } from '@/context/admin-modal-context';
import styles from './page.module.css';

// İkonlar
import { FaEye, FaEyeSlash, FaLock, FaKey } from 'react-icons/fa';

export default function ChangePasswordPage() {
  const router = useRouter();
  const { openModal } = useAdminModal();

  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  
  const [showCurrent, setShowCurrent] = useState(false);
  const [showNew, setShowNew] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);

  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Validation
    if (newPassword !== confirmPassword) {
      openModal({ type: 'error', title: 'Error', message: 'Passwords do not match!' });
      return;
    }

    if (newPassword.length < 6) {
        openModal({ type: 'error', title: 'Weak Password', message: 'New password must be at least 6 characters long.' });
        return;
    }

    setIsLoading(true);

    try {
      const response = await fetch('/api/admin/change-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ currentPassword, newPassword }),
      });

      const data = await response.json();

      if (response.ok) {
        openModal({
            type: 'success',
            title: 'Password Changed! 🔒',
            message: 'Your password has been updated successfully.',
            confirmText: 'Back to Dashboard',
            onConfirm: () => router.push('/admin')
        });
        // Inputları təmizlə
        setCurrentPassword('');
        setNewPassword('');
        setConfirmPassword('');
      } else {
        openModal({ type: 'error', title: 'Failed', message: data.error || 'Could not change password.' });
      }
    } catch {
      openModal({ type: 'error', title: 'Error', message: 'Something went wrong. Please try again.' });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className={styles.container}>
      
      <div className={styles.header}>
        <h1 className={styles.title}>Change Password</h1>
        <p className={styles.subtitle}>Secure your admin account with a new password</p>
      </div>

      <div className={styles.card}>
        <form onSubmit={handleSubmit}>
          
          {/* CARİ ŞİFRƏ */}
          <div className={styles.formGroup}>
            <label className={styles.label}>Current Password</label>
            <div className={styles.inputWrapper}>
              <input
                type={showCurrent ? "text" : "password"}
                className={styles.input}
                value={currentPassword}
                onChange={(e) => setCurrentPassword(e.target.value)}
                required
                placeholder="Enter current password"
              />
              <button 
                type="button" 
                className={styles.eyeButton} 
                onClick={() => setShowCurrent(!showCurrent)}
              >
                {showCurrent ? <FaEyeSlash /> : <FaEye />}
              </button>
            </div>
          </div>

          {/* YENİ ŞİFRƏ */}
          <div className={styles.formGroup}>
            <label className={styles.label}>New Password</label>
            <div className={styles.inputWrapper}>
              <input
                type={showNew ? "text" : "password"}
                className={styles.input}
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                required
                placeholder="Enter new password"
                minLength={6}
              />
              <button 
                type="button" 
                className={styles.eyeButton} 
                onClick={() => setShowNew(!showNew)}
              >
                {showNew ? <FaEyeSlash /> : <FaEye />}
              </button>
            </div>
          </div>

          {/* TƏKRAR ŞİFRƏ */}
          <div className={styles.formGroup}>
            <label className={styles.label}>Confirm New Password</label>
            <div className={styles.inputWrapper}>
              <input
                type={showConfirm ? "text" : "password"}
                className={styles.input}
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                required
                placeholder="Repeat new password"
                minLength={6}
              />
              <button 
                type="button" 
                className={styles.eyeButton} 
                onClick={() => setShowConfirm(!showConfirm)}
              >
                {showConfirm ? <FaEyeSlash /> : <FaEye />}
              </button>
            </div>
          </div>

          <div className={styles.buttonGroup}>
            <button
              type="button"
              className={styles.cancelBtn}
              onClick={() => router.back()}
            >
              Cancel
            </button>
            <button
              type="submit"
              className={styles.submitBtn}
              disabled={isLoading}
            >
              {isLoading ? 'Updating...' : 'Update Password'}
            </button>
          </div>

        </form>
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Image from 'next/image';
import { useRouter, useParams } from 'next/navigation';
import Link from 'next/link';
import { getCollectionById, updateCollection } from '@/lib/collections';
import { useAdminModal } from '@/context/admin-modal-context';
import styles from '../collections.module.css';
import { getApiBaseUrl } from '@/lib/api-base';

import { FaSave, FaLayerGroup, FaCloudUploadAlt, FaTimes } from 'react-icons/fa';

export default function EditCollectionPage() {
  const router = useRouter();
  const params = useParams();
  const id = params?.id as string;
  const { openModal } = useAdminModal();

  const [loading, setLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);

  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  
  const [currentImageUrl, setCurrentImageUrl] = useState<string | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  // Data Gətir
  useEffect(() => {
    if (id) {
      const fetchData = async () => {
        try {
          const token = localStorage.getItem('accessToken') || undefined;
          const data = await getCollectionById(id, token);
          setName(data.name);
          setDescription(data.description || '');
          if(data.coverImageUrl) setCurrentImageUrl(data.coverImageUrl); 
        } catch (error) {
          console.error(error);
          openModal({ type: 'error', title: 'Error', message: 'Collection not found.' });
          router.push('/admin/collections');
        } finally {
          setInitialLoading(false);
        }
      };
      fetchData();
    }
  }, [id, router]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const selected = e.target.files[0];
      setFile(selected);
      setPreviewUrl(URL.createObjectURL(selected));
    }
  };

  const removeNewFile = () => {
    setFile(null);
    setPreviewUrl(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const token = localStorage.getItem('accessToken') || '';
      // updateCollection funksiyası file optional qəbul edir
      await updateCollection(id, name, description, file, token);
      
      openModal({
        type: 'success',
        title: 'Updated Successfully!',
        message: 'Collection changes have been saved.',
        confirmText: 'Back to List',
        onConfirm: () => router.push('/admin/collections')
      });

    } catch (error: any) {
      openModal({ type: 'error', title: 'Error', message: error.message || 'Failed to update' });
    } finally {
      setLoading(false);
    }
  };

  const getFullImageUrl = (url: string) => {
    if (!url) return '';
    if (url.startsWith('http')) return url;
    return `${getApiBaseUrl()}${url}`;
  };

  if (initialLoading) return <div style={{padding: 40, textAlign: 'center'}}>Loading...</div>;

  return (
    <form onSubmit={handleSubmit} className={styles.container}>
      <div className={styles.header}>
        <h1 className={styles.title}>Edit Collection</h1>
        <div className={styles.headerActions}>
          <Link href="/admin/collections" className={styles.cancelBtn}>Cancel</Link>
          <button type="submit" className={styles.saveBtn} disabled={loading}>
            <FaSave /> {loading ? 'Saving...' : 'Save Changes'}
          </button>
        </div>
      </div>

      <div className={styles.formGrid}>
        <div className={styles.card}>
          <div className={styles.cardTitle}><FaLayerGroup /> Basic Information</div>
          <div className={styles.formGroup}>
            <label className={styles.label}>Name</label>
            <input type="text" className={styles.input} value={name} onChange={(e) => setName(e.target.value)} required />
          </div>
          <div className={styles.formGroup}>
            <label className={styles.label}>Description</label>
            <textarea className={styles.textarea} value={description} onChange={(e) => setDescription(e.target.value)} />
          </div>
        </div>

        <div className={styles.card}>
          <div className={styles.cardTitle}><FaCloudUploadAlt /> Cover Image</div>
          
          {previewUrl ? (
            <div className={styles.previewWrapper}>
              <img src={previewUrl} alt="New" className={styles.previewImage} />
              <button type="button" onClick={removeNewFile} className={styles.removeImageBtn}><FaTimes /></button>
            </div>
          ) : (
            <>
              {currentImageUrl && (
                <div className={styles.previewWrapper} style={{ marginBottom: 15, borderStyle: 'solid', position: 'relative' }}>
                  <Image src={getFullImageUrl(currentImageUrl)} alt="Current" fill className={styles.previewImage} sizes="300px" />
                  <span style={{position: 'absolute', bottom: 5, left: 5, background: '#111', color: '#fff', fontSize: 10, padding: '2px 6px', borderRadius: 4}}>Current</span>
                </div>
              )}
              
              <label className={styles.uploadArea}>
                <input type="file" accept="image/*" hidden onChange={handleFileChange} />
                <div style={{fontSize: 28, color: '#ccc', marginBottom: 8}}><FaCloudUploadAlt /></div>
                <span style={{fontSize: 13, color: '#666', fontWeight: 500}}>
                   {currentImageUrl ? 'Change Image' : 'Upload Image'}
                </span>
              </label>
            </>
          )}
        </div>
      </div>
    </form>
  );
}

'use client';

import React, { useState } from 'react';
import Image from 'next/image';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { createCollection } from '@/lib/collections';
import { useAdminModal } from '@/context/admin-modal-context';
import styles from '../collections.module.css';

import { FaSave, FaLayerGroup, FaCloudUploadAlt, FaTimes } from 'react-icons/fa';

export default function NewCollectionPage() {
  const router = useRouter();
  const { openModal } = useAdminModal();
  const [loading, setLoading] = useState(false);

  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const selected = e.target.files[0];
      setFile(selected);
      setPreviewUrl(URL.createObjectURL(selected));
    }
  };

  const removeFile = () => {
    setFile(null);
    setPreviewUrl(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) {
      openModal({ type: 'error', title: 'Error', message: 'Collection Name is required!' });
      return;
    }
    if (!file) {
        openModal({ type: 'error', title: 'Missing Image', message: 'Please upload a cover image.' });
        return;
    }

    setLoading(true);
    try {
      const token = localStorage.getItem('accessToken') || '';
      await createCollection(name, description, file, token);

      openModal({
        type: 'success',
        title: 'Collection Created! 🎉',
        message: 'New collection has been added successfully.',
        confirmText: 'Go to Collections',
        onConfirm: () => router.push('/admin/collections')
      });
      
    } catch (error: any) {
      console.error(error);
      openModal({ type: 'error', title: 'Failed', message: error.message || 'Could not create collection' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className={styles.container}>
      <div className={styles.header}>
        <h1 className={styles.title}>New Collection</h1>
        <div className={styles.headerActions}>
          <Link href="/admin/collections" className={styles.cancelBtn}>Cancel</Link>
          <button type="submit" className={styles.saveBtn} disabled={loading}>
            <FaSave /> {loading ? 'Saving...' : 'Save Collection'}
          </button>
        </div>
      </div>

      <div className={styles.formGrid}>
        
        {/* SOL: Məlumatlar */}
        <div className={styles.card}>
          <div className={styles.cardTitle}><FaLayerGroup /> Basic Information</div>
          
          <div className={styles.formGroup}>
            <label className={styles.label}>Collection Name</label>
            <input 
              type="text" className={styles.input} 
              value={name} onChange={(e) => setName(e.target.value)} 
              placeholder="e.g. Summer 2024" required 
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.label}>Description</label>
            <textarea 
              className={styles.textarea} 
              value={description} onChange={(e) => setDescription(e.target.value)} 
              placeholder="Describe this collection..." 
            />
          </div>
        </div>

        {/* SAĞ: Şəkil */}
        <div className={styles.card}>
          <div className={styles.cardTitle}><FaCloudUploadAlt /> Cover Image</div>
          
          {!previewUrl ? (
            <label className={styles.uploadArea}>
              <input type="file" accept="image/*" hidden onChange={handleFileChange} />
              <div style={{fontSize: 28, color: '#ccc', marginBottom: 8}}><FaCloudUploadAlt /></div>
              <span style={{fontSize: 13, color: '#666', fontWeight: 500}}>Upload Cover Image</span>
            </label>
          ) : (
            <div className={styles.previewWrapper} style={{ position: 'relative' }}>
              <Image src={previewUrl} alt="Preview" fill className={styles.previewImage} sizes="300px" unoptimized />
              <button type="button" onClick={removeFile} className={styles.removeImageBtn}>
                <FaTimes />
              </button>
            </div>
          )}
        </div>

      </div>
    </form>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { getCollections, deleteCollection, BackendCollection } from '@/lib/collections';
import { getCached, setCached } from '@/lib/admin-prefetch-cache';
import AdminTableSkeleton from '../components/AdminTableSkeleton';
import { AdminCheckbox } from '../components/AdminCheckbox';
import { useAdminModal } from '@/context/admin-modal-context';
import shared from '../components/admin-shared.module.css';
import styles from './collections.module.css';
import { FaPlus, FaEdit, FaTrash, FaLayerGroup, FaImage, FaSearch } from 'react-icons/fa';
import { getApiBaseUrl } from '@/lib/api-base';

export default function CollectionsPage() {
  const cached = getCached<BackendCollection[]>('collections');
  const [collections, setCollections] = useState<BackendCollection[]>(Array.isArray(cached) ? cached : []);
  const [loading, setLoading] = useState(!cached);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const { openModal } = useAdminModal();

  const fetchCollections = async (showLoader = true) => {
    try {
      if (showLoader) setLoading(true);
      const data = await getCollections();
      const list = Array.isArray(data) ? data : [];
      setCollections(list);
      setCached('collections', list);
    } catch (error) {
      console.error('Failed to fetch collections', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCollections(!cached);
  }, []);

  // DELETE MODAL
  const handleDelete = (id: number) => {
    openModal({
      type: 'warning',
      title: 'Delete Collection?',
      message: 'Are you sure you want to delete this collection? Products in this collection will be updated.',
      confirmText: 'Yes, Delete',
      cancelText: 'Cancel',
      onConfirm: async () => {
        const token = localStorage.getItem('accessToken') || '';
        await deleteCollection(id, token);
        setCollections(prev => prev.filter(c => c.id !== id));
        setSelectedIds(prev => prev.filter(selectedId => selectedId !== id));
      }
    });
  };

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) setSelectedIds(collections.map(c => c.id));
    else setSelectedIds([]);
  };

  const handleSelectOne = (id: number) => {
    setSelectedIds(prev =>
      prev.includes(id) ? prev.filter(item => item !== id) : [...prev, id]
    );
  };

  const handleBulkDelete = () => {
    openModal({
      type: 'warning',
      title: 'Toplu Silinmə',
      message: `Seçilmiş ${selectedIds.length} kolleksiyanı silmək istədiyinizə əminsiniz? Bu geriyə alına bilməz.`,
      confirmText: 'Bəli, Sil',
      cancelText: 'Ləğv et',
      onConfirm: async () => {
        const token = localStorage.getItem('accessToken') || '';
        setLoading(true);
        try {
          const results = await Promise.allSettled(
            selectedIds.map(id => deleteCollection(id, token))
          );
          const successIds = results
            .map((r, idx) => r.status === 'fulfilled' ? selectedIds[idx] : null)
            .filter(Boolean) as number[];
          setCollections(prev => prev.filter(item => !successIds.includes(item.id)));
          setSelectedIds([]);
        } catch (error) {
          console.error("Toplu silinmə xətası", error);
        } finally {
          setLoading(false);
        }
      }
    });
  };

  const getImageUrl = (url: string) => {
    if (!url) return null;
    if (url.startsWith('http')) return url;
    return `${getApiBaseUrl()}${url}`;
  };

  return (
    <div className={shared.container}>
      <div className={shared.header}>
        <h1 className={shared.title}>Collections</h1>
        <div className={shared.headerActions}>
          {selectedIds.length > 0 && (
            <button onClick={handleBulkDelete} className={`${shared.addButton} ${shared.bulkDeleteBtn}`}>
              <FaTrash /> Seçilmişləri Sil ({selectedIds.length})
            </button>
          )}
          <Link href="/admin/collections/new" className={shared.addButton}>
            <FaPlus /> New Collection
          </Link>
        </div>
      </div>

      <div className={shared.filtersBar}>
        <div className={shared.searchWrapper}>
          <FaSearch className={shared.searchIcon} />
          <input
            type="text"
            placeholder="Search collections..."
            className={shared.searchInput}
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className={shared.tableCard}>
        {loading ? (
          <AdminTableSkeleton rows={8} />
        ) : collections.length === 0 ? (
          <div className={shared.emptyState}>
            <FaLayerGroup size={48} className={shared.emptyStateIcon} />
            <p>No collections found.</p>
          </div>
        ) : (
          (() => {
            const filtered = collections.filter(col => 
              col.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
              col.description?.toLowerCase().includes(searchTerm.toLowerCase())
            );

            if (filtered.length === 0 && searchTerm) {
              return (
                <div className={shared.emptyState}>
                  <FaSearch size={48} className={shared.emptyStateIcon} />
                  <p>No collections match your search "{searchTerm}".</p>
                </div>
              );
            }

            return (
              <table className={shared.table}>
                <thead>
                  <tr>
                    <th>
                      <AdminCheckbox
                        checked={filtered.length > 0 && selectedIds.length === filtered.length}
                        onChange={(e) => {
                          if (e.target.checked) setSelectedIds(filtered.map(c => c.id));
                          else setSelectedIds([]);
                        }}
                        indeterminate={selectedIds.length > 0 && selectedIds.length < filtered.length}
                        aria-label="Hamısını seç"
                      />
                    </th>
                    <th>Collection</th>
                    <th>Description</th>
                    <th style={{ textAlign: 'right' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((col) => {
                    const imgUrl = getImageUrl(col.coverImageUrl);
                    return (
                      <tr key={col.id} className={selectedIds.includes(col.id) ? shared.selected : ''}>
                        <td>
                          <AdminCheckbox
                            checked={selectedIds.includes(col.id)}
                            onChange={() => handleSelectOne(col.id)}
                            aria-label={`Kolleksiya ${col.name} seç`}
                          />
                        </td>
                        <td>
                          <div className={styles.cellContent}>
                            <div className={styles.imageWrapper}>
                              {imgUrl ? (
                                <Image src={imgUrl} alt={col.name} width={60} height={40} className={styles.image} loading="lazy" />
                              ) : (
                                <div style={{width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#ccc'}}>
                                  <FaImage />
                                </div>
                              )}
                            </div>
                            <div className={styles.nameInfo}>
                               <span className={styles.name}>{col.name}</span>
                               <span className={styles.idBadge}>ID: #{col.id}</span>
                            </div>
                          </div>
                        </td>
                        <td style={{color: '#666', maxWidth: 300}}>
                          {col.description ? col.description.substring(0, 60) + (col.description.length > 60 ? '...' : '') : '—'}
                        </td>
                        <td>
                          <div className={shared.actions}>
                            <Link href={`/admin/collections/${col.id}`} className={`${shared.actionBtn} ${shared.editBtn}`} title="Edit">
                              <FaEdit />
                            </Link>
                            <button onClick={() => handleDelete(col.id)} className={`${shared.actionBtn} ${shared.deleteBtn}`} title="Delete">
                              <FaTrash />
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            );
          })()
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { useRouter, useParams } from 'next/navigation';
import Link from 'next/link';
import { getColorById, updateColor } from '@/lib/colors';
import { useAdminModal } from '@/context/admin-modal-context';
import styles from '../colors.module.css';

import { FaSave, FaPalette } from 'react-icons/fa';

export default function EditColorPage() {
  const router = useRouter();
  const params = useParams();
  const id = params?.id as string;
  const { openModal } = useAdminModal();

  const [formData, setFormData] = useState({ name: '', hexCode: '' });
  const [loading, setLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);

  // Data Gətir
  useEffect(() => {
    if (id) {
      const fetchData = async () => {
        try {
          const token = localStorage.getItem('accessToken');
          const data = await getColorById(id, token || undefined);
          setFormData({ name: data.name || '', hexCode: data.hexCode || '#000000' });
        } catch (error) {
          console.error('Color not found', error);
          openModal({ type: 'error', title: 'Error', message: 'Color not found.' });
          router.push('/admin/colors');
        } finally {
          setInitialLoading(false);
        }
      };
      fetchData();
    }
  }, [id, router]);

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const token = localStorage.getItem('accessToken') || '';
      await updateColor(id, formData, token);

      openModal({
        type: 'success',
        title: 'Updated Successfully!',
        message: 'Color details have been saved.',
        confirmText: 'Back to List',
        onConfirm: () => router.push('/admin/colors')
      });

    } catch (error: any) {
      openModal({ type: 'error', title: 'Error', message: error.message || 'Failed to update' });
    } finally {
      setLoading(false);
    }
  };

  if (initialLoading) return <div style={{padding: 40, textAlign: 'center'}}>Loading...</div>;

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h1 className={styles.title}>Edit Color</h1>
        <div className={styles.headerActions}>
            <Link href="/admin/colors" className={styles.cancelBtn}>Cancel</Link>
            <button form="editColorForm" type="submit" className={styles.saveBtn} disabled={loading}>
              <FaSave /> {loading ? 'Saving...' : 'Save Changes'}
            </button>
        </div>
      </div>

      <div className={styles.simpleCard}>
        <div className={styles.cardTitle}><FaPalette /> Color Details</div>
        
        <form id="editColorForm" onSubmit={handleUpdate}>
          <div className={styles.formGroup}>
            <label className={styles.label}>Color Name</label>
            <input 
              type="text" className={styles.input} 
              required
              value={formData.name}
              onChange={(e) => setFormData({...formData, name: e.target.value})}
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.label}>Hex Code</label>
            <div className={styles.colorPickerWrapper}>
              <input 
                type="color" className={styles.colorInput}
                value={formData.hexCode}
                onChange={(e) => setFormData({...formData, hexCode: e.target.value})}
              />
              <input 
                type="text" className={styles.input} 
                value={formData.hexCode}
                onChange={(e) => setFormData({...formData, hexCode: e.target.value})}
                pattern="^#([A-Fa-f0-9]{6}|[A-Fa-f0-9]{3})$"
                required
              />
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { createColor } from '@/lib/colors';
import { useAdminModal } from '@/context/admin-modal-context';
import styles from '../colors.module.css';

import { FaSave, FaPalette } from 'react-icons/fa';

export default function NewColorPage() {
  const router = useRouter();
  const { openModal } = useAdminModal();
  const [formData, setFormData] = useState({ name: '', hexCode: '#000000' });
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.hexCode) {
      openModal({ type: 'error', title: 'Error', message: 'All fields are required!' });
      return;
    }

    setLoading(true);
    try {
      const token = localStorage.getItem('accessToken') || '';
      await createColor(formData, token);

      openModal({
        type: 'success',
        title: 'Color Added! 🎨',
        message: 'New color has been added successfully.',
        confirmText: 'Go to Colors',
        onConfirm: () => router.push('/admin/colors')
      });
      
    } catch (error: any) {
      console.error(error);
      openModal({ type: 'error', title: 'Failed', message: error.message || 'Could not create color' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h1 className={styles.title}>New Color</h1>
        <div className={styles.headerActions}>
            <Link href="/admin/colors" className={styles.cancelBtn}>Cancel</Link>
            <button form="colorForm" type="submit" className={styles.saveBtn} disabled={loading}>
              <FaSave /> {loading ? 'Saving...' : 'Save Color'}
            </button>
        </div>
      </div>

      <div className={styles.simpleCard}>
        <div className={styles.cardTitle}><FaPalette /> Color Details</div>
        
        <form id="colorForm" onSubmit={handleSubmit}>
          <div className={styles.formGroup}>
            <label className={styles.label}>Color Name</label>
            <input 
              type="text" className={styles.input} 
              placeholder="e.g. Midnight Blue" required 
              value={formData.name}
              onChange={(e) => setFormData({...formData, name: e.target.value})}
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.label}>Hex Code</label>
            <div className={styles.colorPickerWrapper}>
              <input 
                type="color" className={styles.colorInput}
                value={formData.hexCode}
                onChange={(e) => setFormData({...formData, hexCode: e.target.value})}
              />
              <input 
                type="text" className={styles.input} 
                value={formData.hexCode}
                onChange={(e) => setFormData({...formData, hexCode: e.target.value})}
                placeholder="#000000"
                pattern="^#([A-Fa-f0-9]{6}|[A-Fa-f0-9]{3})$"
                required
              />
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { getCached, setCached } from "@/lib/admin-prefetch-cache";
import AdminTableSkeleton from "../components/AdminTableSkeleton";
import { AdminCheckbox } from "../components/AdminCheckbox";
import Link from "next/link";
import { getColors, deleteColor, BackendColor } from "@/lib/colors";
import { useAdminModal } from "@/context/admin-modal-context";
import shared from "../components/admin-shared.module.css";
import styles from "./colors.module.css";
import { FaPlus, FaEdit, FaTrash, FaPalette, FaSearch } from "react-icons/fa";

export default function ColorsPage() {
  const cached = getCached<BackendColor[]>("colors");
  const [colors, setColors] = useState<BackendColor[]>(
    Array.isArray(cached) ? cached : [],
  );
  const [loading, setLoading] = useState(!cached);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const { openModal } = useAdminModal();

  const fetchColors = async (showLoader = true) => {
    try {
      if (showLoader) setLoading(true);
      const data = await getColors();
      const list = Array.isArray(data) ? data : [];
      setColors(list);
      setCached("colors", list);
    } catch (error) {
      console.error("Failed to fetch colors", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchColors(!cached);
  }, []);

  // DELETE MODAL
  const handleDelete = (id: number) => {
    openModal({
      type: "warning",
      title: "Delete Color?",
      message:
        "Are you sure you want to delete this color? Products using this color will be affected.",
      confirmText: "Yes, Delete",
      cancelText: "Cancel",
      onConfirm: async () => {
        const token = localStorage.getItem("accessToken") || "";
        await deleteColor(id, token);
        setColors((prev) => prev.filter((c) => c.id !== id));
        setSelectedIds((prev) =>
          prev.filter((selectedId) => selectedId !== id),
        );
      },
    });
  };

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) setSelectedIds(colors.map((c) => c.id));
    else setSelectedIds([]);
  };

  const handleSelectOne = (id: number) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id],
    );
  };

  const handleBulkDelete = () => {
    openModal({
      type: "warning",
      title: "Toplu Silinmə",
      message: `Seçilmiş ${selectedIds.length} rəngi silmək istədiyinizə əminsiniz? Bu geriyə alına bilməz.`,
      confirmText: "Bəli, Sil",
      cancelText: "Ləğv et",
      onConfirm: async () => {
        const token = localStorage.getItem("accessToken") || "";
        setLoading(true);
        try {
          const results = await Promise.allSettled(
            selectedIds.map((id) => deleteColor(id, token)),
          );
          const successIds = results
            .map((r, idx) =>
              r.status === "fulfilled" ? selectedIds[idx] : null,
            )
            .filter(Boolean) as number[];
          setColors((prev) =>
            prev.filter((item) => !successIds.includes(item.id)),
          );
          setSelectedIds([]);
        } catch (error) {
          console.error("Toplu silinmə xətası", error);
        } finally {
          setLoading(false);
        }
      },
    });
  };

  return (
    <div className={shared.container}>
      <div className={shared.header}>
        <h1 className={shared.title}>Colors</h1>
        <div className={shared.headerActions}>
          {selectedIds.length > 0 && (
            <button
              onClick={handleBulkDelete}
              className={`${shared.addButton} ${shared.bulkDeleteBtn}`}
            >
              <FaTrash /> Seçilmişləri Sil ({selectedIds.length})
            </button>
          )}
          <Link href="/admin/colors/new" className={shared.addButton}>
            <FaPlus /> New Color
          </Link>
        </div>
      </div>

      <div className={shared.filtersBar}>
        <div className={shared.searchWrapper}>
          <FaSearch className={shared.searchIcon} />
          <input
            type="text"
            placeholder="Search colors..."
            className={shared.searchInput}
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className={shared.tableCard}>
        {loading ? (
          <AdminTableSkeleton rows={8} />
        ) : colors.length === 0 ? (
          <div className={shared.emptyState}>
            <FaPalette size={48} className={shared.emptyStateIcon} />
            <p>No colors found.</p>
          </div>
        ) : (
          (() => {
            const filtered = colors.filter(
              (color) =>
                color.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                (color.hexCode ?? "")
                  .toLowerCase()
                  .includes(searchTerm.toLowerCase()),
            );

            if (filtered.length === 0 && searchTerm) {
              return (
                <div className={shared.emptyState}>
                  <FaSearch size={48} className={shared.emptyStateIcon} />
                  <p>No colors match your search "{searchTerm}".</p>
                </div>
              );
            }

            return (
              <table className={shared.table}>
                <thead>
                  <tr>
                    <th>
                      <AdminCheckbox
                        checked={
                          filtered.length > 0 &&
                          selectedIds.length === filtered.length
                        }
                        onChange={(e) => {
                          if (e.target.checked)
                            setSelectedIds(filtered.map((c) => c.id));
                          else setSelectedIds([]);
                        }}
                        indeterminate={
                          selectedIds.length > 0 &&
                          selectedIds.length < filtered.length
                        }
                        aria-label="Hamısını seç"
                      />
                    </th>
                    <th>Color Name</th>
                    <th>Hex Code</th>
                    <th style={{ textAlign: "right" }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((color) => (
                    <tr
                      key={color.id}
                      className={
                        selectedIds.includes(color.id) ? shared.selected : ""
                      }
                    >
                      <td>
                        <AdminCheckbox
                          checked={selectedIds.includes(color.id)}
                          onChange={() => handleSelectOne(color.id)}
                          aria-label={`Rəng ${color.name} seç`}
                        />
                      </td>
                      <td>
                        <div className={styles.cellContent}>
                          <div
                            className={styles.colorCircle}
                            style={{ backgroundColor: color.hexCode }}
                          />
                          <div className={styles.nameInfo}>
                            <span className={styles.name}>{color.name}</span>
                            <span className={styles.idBadge}>
                              ID: #{color.id}
                            </span>
                          </div>
                        </div>
                      </td>
                      <td>
                        <span className={styles.hexBadge}>{color.hexCode}</span>
                      </td>
                      <td>
                        <div className={shared.actions}>
                          <Link
                            href={`/admin/colors/${color.id}`}
                            className={`${shared.actionBtn} ${shared.editBtn}`}
                            title="Edit"
                          >
                            <FaEdit />
                          </Link>
                          <button
                            onClick={() => handleDelete(color.id)}
                            className={`${shared.actionBtn} ${shared.deleteBtn}`}
                            title="Delete"
                          >
                            <FaTrash />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            );
          })()
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { useRouter, useParams } from 'next/navigation';
import { getMessageById, ContactMessage } from '@/lib/contact';
import { useAdminModal } from '@/context/admin-modal-context';
import styles from '../contact.module.css';

import { FaArrowLeft, FaUser, FaEnvelope, FaPhone, FaCalendarAlt } from 'react-icons/fa';

export default function ContactDetailPage() {
  const params = useParams();
  const id = params?.id as string;
  const [message, setMessage] = useState<ContactMessage | null>(null);
  const [loading, setLoading] = useState(true);
  const { openModal } = useAdminModal();
  const router = useRouter();

  useEffect(() => {
    if (!id) return;
    const fetchDetail = async () => {
      try {
        const token = localStorage.getItem('accessToken') || '';
        const data = await getMessageById(id, token);
        setMessage(data);
      } catch (error) {
        console.error('Mesaj tapılmadı');
        openModal({ type: 'error', title: 'Error', message: 'Message not found.' });
        router.push('/admin/contact');
      } finally {
        setLoading(false);
      }
    };
    fetchDetail();
  }, [id, router]);

  if (loading) return <div style={{padding: 40, textAlign: 'center'}}>Loading...</div>;
  if (!message) return null;

  return (
    <div className={styles.container}>
      <Link href="/admin/contact" className={styles.backLink}>
        <FaArrowLeft /> Back to Inbox
      </Link>
      
      <div className={styles.detailCard}>
        <div className={styles.detailHeader}>
           <h1 className={styles.detailTitle}>{message.subject}</h1>
           <span className={`${styles.statusBadge} ${!message.isRead ? styles.statusNew : styles.statusRead}`}>
                {!message.isRead ? 'Unread' : 'Read'}
           </span>
        </div>

        <div className={styles.metaInfo}>
          <div className={styles.metaItem}>
            <span className={styles.metaLabel}><FaUser style={{marginRight: 5}}/> Sender</span>
            <span className={styles.metaValue}>{message.fullName}</span>
          </div>
          <div className={styles.metaItem}>
            <span className={styles.metaLabel}><FaEnvelope style={{marginRight: 5}}/> Email</span>
            <span className={styles.metaValue}>
                <a href={`mailto:${message.email}`} style={{color: '#2563eb', textDecoration: 'none'}}>{message.email}</a>
            </span>
          </div>
          <div className={styles.metaItem}>
            <span className={styles.metaLabel}><FaPhone style={{marginRight: 5}}/> Phone</span>
            <span className={styles.metaValue}>{message.phoneNumber || '—'}</span>
          </div>
          <div className={styles.metaItem}>
            <span className={styles.metaLabel}><FaCalendarAlt style={{marginRight: 5}}/> Date</span>
            <span className={styles.metaValue}>
                {message.createdAt ? new Date(message.createdAt).toLocaleString() : '—'}
            </span>
          </div>
        </div>

        <div>
            <span className={styles.metaLabel}>Message Body</span>
            <div className={styles.messageBody}>
