'use client';

import React, { useEffect, useState } from 'react';
import AdminTableSkeleton from '../components/AdminTableSkeleton';
import { AdminCheckbox } from '../components/AdminCheckbox';
import Link from 'next/link';
import { getMessages, deleteMessage, ContactMessage, ContactResponse } from '@/lib/contact';
import { getCached, setCached } from '@/lib/admin-prefetch-cache';
import { useAdminModal } from '@/context/admin-modal-context';
import shared from '../components/admin-shared.module.css';
import styles from './contact.module.css';
import { FaTrash, FaEye, FaInbox, FaSearch } from 'react-icons/fa';

function parseMessages(data: ContactMessage[] | ContactResponse): ContactMessage[] {
  if (Array.isArray(data)) return data;
  if ('messages' in data) return data.messages;
  return [];
}

export default function ContactListPage() {
  const [page, setPage] = useState(1);
  const cached = getCached<ContactMessage[]>('contact');
  const [messages, setMessages] = useState<ContactMessage[]>(Array.isArray(cached) ? cached : []);
  const [loading, setLoading] = useState(!cached);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const { openModal } = useAdminModal();

  useEffect(() => {
    const fetchMessages = async (showLoader = true) => {
      if (showLoader) setLoading(true);
      try {
        const token = localStorage.getItem('accessToken') || '';
        const data = await getMessages(page, 10, token);
        const list = parseMessages(data);
        setMessages(list);
        if (page === 1) setCached('contact', list);
      } catch (error) {
        console.error('Mesajlar gəlmədi:', error);
      } finally {
        setLoading(false);
      }
    };

    const hasCached = page === 1 && getCached<ContactMessage[]>('contact');
    fetchMessages(!hasCached);
  }, [page]);

  // DELETE MODAL
  const handleDelete = (id: number) => {
    openModal({
      type: 'warning',
      title: 'Delete Message?',
      message: 'Are you sure you want to delete this message? This action cannot be undone.',
      confirmText: 'Yes, Delete',
      cancelText: 'Cancel',
      onConfirm: async () => {
        const token = localStorage.getItem('accessToken') || '';
        await deleteMessage(id, token);
        setMessages(prev => prev.filter(m => m.id !== id));
        setSelectedIds(prev => prev.filter(selectedId => selectedId !== id));
      }
    });
  };

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) setSelectedIds(messages.map(m => m.id));
    else setSelectedIds([]);
  };

  const handleSelectOne = (id: number) => {
    setSelectedIds(prev =>
      prev.includes(id) ? prev.filter(item => item !== id) : [...prev, id]
    );
  };

  const handleBulkDelete = () => {
    openModal({
      type: 'warning',
      title: 'Toplu Silinmə',
      message: `Seçilmiş ${selectedIds.length} mesajı silmək istədiyinizə əminsiniz? Bu geriyə alına bilməz.`,
      confirmText: 'Bəli, Sil',
      cancelText: 'Ləğv et',
      onConfirm: async () => {
        const token = localStorage.getItem('accessToken') || '';
        setLoading(true);
        try {
          const results = await Promise.allSettled(
            selectedIds.map(id => deleteMessage(id, token))
          );
          const successIds = results
            .map((r, idx) => r.status === 'fulfilled' ? selectedIds[idx] : null)
            .filter(Boolean) as number[];
          setMessages(prev => prev.filter(item => !successIds.includes(item.id)));
          setSelectedIds([]);
        } catch (error) {
          console.error("Toplu silinmə xətası", error);
        } finally {
          setLoading(false);
        }
      }
    });
  };

  const formatDate = (dateString?: string) => {
    if (!dateString) return '-';
    try {
        return new Date(dateString).toLocaleDateString('en-GB', {
            day: '2-digit', month: 'short', year: 'numeric',
            hour: '2-digit', minute: '2-digit'
        });
    } catch {
        return dateString;
    }
  };

  return (
    <div className={shared.container}>
      <div className={shared.header}>
        <h1 className={shared.title}>Inbox ({messages.length})</h1>
        {selectedIds.length > 0 && (
          <button onClick={handleBulkDelete} className={`${shared.addButton} ${shared.bulkDeleteBtn}`}>
            <FaTrash /> Seçilmişləri Sil ({selectedIds.length})
          </button>
        )}
      </div>

      <div className={shared.filtersBar}>
        <div className={shared.searchWrapper}>
          <FaSearch className={shared.searchIcon} />
          <input
            type="text"
            placeholder="Search messages by name, email or subject..."
            className={shared.searchInput}
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className={shared.tableCard}>
        {loading ? (
          <AdminTableSkeleton rows={6} />
        ) : messages.length === 0 ? (
          <div className={shared.emptyState}>
            <FaInbox size={48} className={shared.emptyStateIcon} />
            <p>No messages found.</p>
          </div>
        ) : (
          (() => {
            const filtered = messages.filter(msg => 
              msg.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
              msg.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
              msg.subject.toLowerCase().includes(searchTerm.toLowerCase())
            );

            if (filtered.length === 0 && searchTerm) {
              return (
                <div className={shared.emptyState}>
                  <FaSearch size={48} className={shared.emptyStateIcon} />
                  <p>No messages match your search "{searchTerm}".</p>
                </div>
              );
            }

            return (
              <>
                <table className={shared.table}>
                  <thead>
                    <tr>
                      <th>
                        <AdminCheckbox
                          checked={filtered.length > 0 && selectedIds.length === filtered.length}
                          onChange={(e) => {
                            if (e.target.checked) setSelectedIds(filtered.map(m => m.id));
                            else setSelectedIds([]);
                          }}
                          indeterminate={selectedIds.length > 0 && selectedIds.length < filtered.length}
                          aria-label="Hamısını seç"
                        />
                      </th>
                      <th>Status</th>
                      <th>Date</th>
                      <th>Sender</th>
                      <th>Subject</th>
                      <th>Email</th>
                      <th style={{ textAlign: 'right' }}>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filtered.map((msg) => (
                      <tr
                        key={msg.id}
                        className={`${selectedIds.includes(msg.id) ? shared.selected : ''} ${!msg.isRead ? styles.unreadRow : ''}`}
                      >
                        <td>
                          <AdminCheckbox
                            checked={selectedIds.includes(msg.id)}
                            onChange={() => handleSelectOne(msg.id)}
                            aria-label={`Mesaj ${msg.subject} seç`}
                          />
                        </td>
                        <td>
                            <span className={`${styles.statusBadge} ${!msg.isRead ? styles.statusNew : styles.statusRead}`}>
                            {!msg.isRead ? 'New' : 'Read'}
                            </span>
                        </td>
                        <td style={{color: '#666', fontSize: 13}}>{formatDate(msg.createdAt)}</td>
                        <td style={{fontWeight: 500}}>{msg.fullName}</td>
                        <td>{msg.subject}</td>
                        <td style={{color: '#666'}}>{msg.email}</td>
                        <td>
                          <div className={shared.actions}>
                            <Link href={`/admin/contact/${msg.id}`} className={`${shared.actionBtn} ${shared.viewBtn}`} title="View">
                              <FaEye />
                            </Link>
                            <button onClick={() => handleDelete(msg.id)} className={`${shared.actionBtn} ${shared.deleteBtn}`} title="Delete">
                              <FaTrash />
                            </button>
                          </div>
                        </td>
                        </tr>
                    ))}
                    </tbody>
                </table>

                <div className={shared.pagination}>
                  <button
                    className={shared.pageBtn}
                    disabled={page === 1}
                    onClick={() => setPage(p => p - 1)}
                  >
                    &larr; Previous
                  </button>
                  <span style={{ fontSize: 14, color: '#6b7280', fontWeight: 600 }}>Page {page}</span>
                  <button
                    className={shared.pageBtn}
                    disabled={messages.length < 10}
                    onClick={() => setPage(p => p + 1)}
                  >
                    Next &rarr;
                  </button>
                </div>
              </>
            );
          })()
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Image from 'next/image';
import { useRouter, useParams } from 'next/navigation';
import Link from 'next/link';
import { getDesignerById, updateDesigner } from '@/lib/designers';
import { useAdminModal } from '@/context/admin-modal-context';
import styles from '../designers.module.css';
import { getApiBaseUrl } from '@/lib/api-base';

import { FaSave, FaUserTie, FaCloudUploadAlt, FaTimes } from 'react-icons/fa';

export default function EditDesignerPage() {
  const router = useRouter();
  const params = useParams();
  const id = params?.id as string;
  const { openModal } = useAdminModal();

  const [loading, setLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);

  const [name, setName] = useState('');
  const [biography, setBiography] = useState('');
  
  const [currentImageUrl, setCurrentImageUrl] = useState<string | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  useEffect(() => {
    if (id) {
      const fetchData = async () => {
        try {
          const token = localStorage.getItem('accessToken') || undefined;
          const data = await getDesignerById(id, token);
          setName(data.name);
          setBiography(data.biography || '');
          if(data.imageUrl) setCurrentImageUrl(data.imageUrl); 
        } catch (error) {
          console.error(error);
          openModal({ type: 'error', title: 'Error', message: 'Designer not found.' });
          router.push('/admin/designers');
        } finally {
          setInitialLoading(false);
        }
      };
      fetchData();
    }
  }, [id, router]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const selected = e.target.files[0];
      setFile(selected);
      setPreviewUrl(URL.createObjectURL(selected));
    }
  };

  const removeNewFile = () => {
    setFile(null);
    setPreviewUrl(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const token = localStorage.getItem('accessToken') || '';
      await updateDesigner(id, name, biography, file, token);
      
      openModal({
        type: 'success',
        title: 'Updated Successfully!',
        message: 'Designer details have been saved.',
        confirmText: 'Back to List',
        onConfirm: () => router.push('/admin/designers')
      });

    } catch (error: any) {
      openModal({ type: 'error', title: 'Error', message: error.message || 'Failed to update' });
    } finally {
      setLoading(false);
    }
  };

  const getFullImageUrl = (url: string) => {
    if (!url) return '';
    if (url.startsWith('http')) return url;
    return `${getApiBaseUrl()}${url}`;
  };

  if (initialLoading) return <div style={{padding: 40, textAlign: 'center'}}>Loading...</div>;

  return (
    <form onSubmit={handleSubmit} className={styles.container}>
      <div className={styles.header}>
        <h1 className={styles.title}>Edit Designer</h1>
        <div className={styles.headerActions}>
          <Link href="/admin/designers" className={styles.cancelBtn}>Cancel</Link>
          <button type="submit" className={styles.saveBtn} disabled={loading}>
            <FaSave /> {loading ? 'Saving...' : 'Save Changes'}
          </button>
        </div>
      </div>

      <div className={styles.formGrid}>
        <div className={styles.card}>
          <div className={styles.cardTitle}><FaUserTie /> Profile Info</div>
          <div className={styles.formGroup}>
            <label className={styles.label}>Name</label>
            <input type="text" className={styles.input} value={name} onChange={(e) => setName(e.target.value)} required />
          </div>
          <div className={styles.formGroup}>
            <label className={styles.label}>Biography</label>
            <textarea className={styles.textarea} value={biography} onChange={(e) => setBiography(e.target.value)} />
          </div>
        </div>

        <div className={styles.card}>
          <div className={styles.cardTitle}><FaCloudUploadAlt /> Profile Photo</div>
          
          {previewUrl ? (
            <div className={styles.previewWrapper} style={{ position: 'relative' }}>
              <Image src={previewUrl} alt="New" fill className={styles.previewImage} sizes="300px" unoptimized />
              <button type="button" onClick={removeNewFile} className={styles.removeImageBtn}><FaTimes /></button>
            </div>
          ) : (
            <>
              {currentImageUrl && (
                <div className={styles.previewWrapper} style={{ marginBottom: 15, borderStyle: 'solid', position: 'relative' }}>
                  <Image src={getFullImageUrl(currentImageUrl)} alt="Current" fill className={styles.previewImage} sizes="300px" />
                  <span style={{position: 'absolute', bottom: 5, left: 5, background: '#111', color: '#fff', fontSize: 10, padding: '2px 6px', borderRadius: 4}}>Current</span>
                </div>
              )}
              
              <label className={styles.uploadArea}>
                <input type="file" accept="image/*" hidden onChange={handleFileChange} />
                <div style={{fontSize: 28, color: '#ccc', marginBottom: 8}}><FaCloudUploadAlt /></div>
                <span style={{fontSize: 13, color: '#666', fontWeight: 500}}>
                   {currentImageUrl ? 'Change Photo' : 'Upload Photo'}
                </span>
              </label>
            </>
          )}
        </div>
      </div>
    </form>
  );
}

