        {/* SOL: Məlumatlar */}
        <div className={styles.card}>
          <div className={styles.cardTitle}><FaUserTie /> Profile Info</div>
          
          <div className={styles.formGroup}>
            <label className={styles.label}>Full Name</label>
            <input 
              type="text" className={styles.input} 
              value={name} onChange={(e) => setName(e.target.value)} 
              placeholder="e.g. John Doe" required 
            />
          </div>

          <div className={styles.formGroup}>
            <label className={styles.label}>Biography</label>
            <textarea 
              className={styles.textarea} 
              value={biography} onChange={(e) => setBiography(e.target.value)} 
              placeholder="Short bio about the designer..." 
            />
          </div>
        </div>

        {/* SAĞ: Şəkil */}
        <div className={styles.card}>
          <div className={styles.cardTitle}><FaCloudUploadAlt /> Profile Photo</div>
          
          {!previewUrl ? (
            <label className={styles.uploadArea}>
              <input type="file" accept="image/*" hidden onChange={handleFileChange} />
              <div style={{fontSize: 28, color: '#ccc', marginBottom: 8}}><FaCloudUploadAlt /></div>
              <span style={{fontSize: 13, color: '#666', fontWeight: 500}}>Upload Photo</span>
            </label>
          ) : (
            <div className={styles.previewWrapper} style={{ position: 'relative' }}>
              <Image src={previewUrl} alt="Preview" fill className={styles.previewImage} sizes="300px" unoptimized />
              <button type="button" onClick={removeFile} className={styles.removeImageBtn}>
                <FaTimes />
              </button>
            </div>
          )}
        </div>

      </div>
    </form>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { getDesigners, deleteDesigner, BackendDesigner } from '@/lib/designers';
import { getCached, setCached } from '@/lib/admin-prefetch-cache';
import AdminTableSkeleton from '../components/AdminTableSkeleton';
import { AdminCheckbox } from '../components/AdminCheckbox';
import { useAdminModal } from '@/context/admin-modal-context';
import shared from '../components/admin-shared.module.css';
import styles from './designers.module.css';
import { FaPlus, FaEdit, FaTrash, FaUserTie, FaUser, FaSearch } from 'react-icons/fa';
import { getApiBaseUrl } from '@/lib/api-base';

export default function DesignersPage() {
  const cached = getCached<BackendDesigner[]>('designers');
  const [designers, setDesigners] = useState<BackendDesigner[]>(Array.isArray(cached) ? cached : []);
  const [loading, setLoading] = useState(!cached);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const { openModal } = useAdminModal();

  const fetchDesigners = async (showLoader = true) => {
    try {
      if (showLoader) setLoading(true);
      const data = await getDesigners();
      const list = Array.isArray(data) ? data : [];
      setDesigners(list);
      setCached('designers', list);
    } catch (error) {
      console.error('Failed to fetch designers', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDesigners(!cached);
  }, []);

  // DELETE MODAL
  const handleDelete = (id: number) => {
    openModal({
      type: 'warning',
      title: 'Delete Designer?',
      message: 'Are you sure you want to delete this designer? This action cannot be undone.',
      confirmText: 'Yes, Delete',
      cancelText: 'Cancel',
      onConfirm: async () => {
        const token = localStorage.getItem('accessToken') || '';
        await deleteDesigner(id, token);
        setDesigners(prev => prev.filter(d => d.id !== id));
        setSelectedIds(prev => prev.filter(selectedId => selectedId !== id));
      }
    });
  };

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) setSelectedIds(designers.map(d => d.id));
    else setSelectedIds([]);
  };

  const handleSelectOne = (id: number) => {
    setSelectedIds(prev =>
      prev.includes(id) ? prev.filter(item => item !== id) : [...prev, id]
    );
  };

  const handleBulkDelete = () => {
    openModal({
      type: 'warning',
      title: 'Toplu Silinmə',
      message: `Seçilmiş ${selectedIds.length} dizayneri silmək istədiyinizə əminsiniz? Bu geriyə alına bilməz.`,
      confirmText: 'Bəli, Sil',
      cancelText: 'Ləğv et',
      onConfirm: async () => {
        const token = localStorage.getItem('accessToken') || '';
        setLoading(true);
        try {
          const results = await Promise.allSettled(
            selectedIds.map(id => deleteDesigner(id, token))
          );
          const successIds = results
            .map((r, idx) => r.status === 'fulfilled' ? selectedIds[idx] : null)
            .filter(Boolean) as number[];
          setDesigners(prev => prev.filter(item => !successIds.includes(item.id)));
          setSelectedIds([]);
        } catch (error) {
          console.error("Toplu silinmə xətası", error);
        } finally {
          setLoading(false);
        }
      }
    });
  };

  const getImageUrl = (url: string) => {
    if (!url) return null;
    if (url.startsWith('http')) return url;
    return `${getApiBaseUrl()}${url}`;
  };

  return (
    <div className={shared.container}>
      <div className={shared.header}>
        <h1 className={shared.title}>Designers</h1>
        <div className={shared.headerActions}>
          {selectedIds.length > 0 && (
            <button onClick={handleBulkDelete} className={`${shared.addButton} ${shared.bulkDeleteBtn}`}>
              <FaTrash /> Seçilmişləri Sil ({selectedIds.length})
            </button>
          )}
          <Link href="/admin/designers/new" className={shared.addButton}>
            <FaPlus /> New Designer
          </Link>
        </div>
      </div>

      <div className={shared.filtersBar}>
        <div className={shared.searchWrapper}>
          <FaSearch className={shared.searchIcon} />
          <input
            type="text"
            placeholder="Search designers..."
            className={shared.searchInput}
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className={shared.tableCard}>
        {loading ? (
          <AdminTableSkeleton rows={8} />
        ) : designers.length === 0 ? (
          <div className={shared.emptyState}>
            <FaUserTie size={48} className={shared.emptyStateIcon} />
            <p>No designers found.</p>
          </div>
        ) : (
          (() => {
            const filtered = designers.filter(d => 
              d.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
              d.biography?.toLowerCase().includes(searchTerm.toLowerCase())
            );

            if (filtered.length === 0 && searchTerm) {
              return (
                <div className={shared.emptyState}>
                  <FaSearch size={48} className={shared.emptyStateIcon} />
                  <p>No designers match your search "{searchTerm}".</p>
                </div>
              );
            }

            return (
              <table className={shared.table}>
                <thead>
                  <tr>
                    <th>
                      <AdminCheckbox
                        checked={filtered.length > 0 && selectedIds.length === filtered.length}
                        onChange={(e) => {
                          if (e.target.checked) setSelectedIds(filtered.map(c => c.id));
                          else setSelectedIds([]);
                        }}
                        indeterminate={selectedIds.length > 0 && selectedIds.length < filtered.length}
                        aria-label="Hamısını seç"
                      />
                    </th>
                    <th>Designer</th>
                    <th>Biography</th>
                    <th style={{ textAlign: 'right' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((designer) => {
                    const imgUrl = getImageUrl(designer.imageUrl);
                    return (
                      <tr key={designer.id} className={selectedIds.includes(designer.id) ? shared.selected : ''}>
                        <td>
                          <AdminCheckbox
                            checked={selectedIds.includes(designer.id)}
                            onChange={() => handleSelectOne(designer.id)}
                            aria-label={`Dizayner ${designer.name} seç`}
                          />
                        </td>
                        <td>
                          <div className={styles.cellContent}>
                            <div className={styles.imageWrapper}>
                              {imgUrl ? (
                                <Image src={imgUrl} alt={designer.name} width={48} height={48} className={styles.image} loading="lazy" />
                              ) : (
                                <div style={{width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#ccc'}}>
                                  <FaUser />
                                </div>
                              )}
                            </div>
                            <div className={styles.nameInfo}>
                               <span className={styles.name}>{designer.name}</span>
                               <span className={styles.idBadge}>ID: #{designer.id}</span>
                            </div>
                          </div>
                        </td>
                        <td style={{color: '#666', maxWidth: 300}}>
                          {designer.biography ? designer.biography.substring(0, 60) + (designer.biography.length > 60 ? '...' : '') : '—'}
                        </td>
                        <td>
                          <div className={shared.actions}>
                            <Link href={`/admin/designers/${designer.id}`} className={`${shared.actionBtn} ${shared.editBtn}`} title="Edit">
                              <FaEdit />
                            </Link>
                            <button onClick={() => handleDelete(designer.id)} className={`${shared.actionBtn} ${shared.deleteBtn}`} title="Delete">
                              <FaTrash />
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            );
          })()
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import Link from 'next/link';
import Image from 'next/image';
import styles from './layout.module.css';

import {
  FaBars, FaBox, FaTags, FaTag, FaPalette, FaLock, FaSignOutAlt,
  FaHome, FaPaintBrush, FaFolder, FaEnvelope, FaBuilding, FaCube
} from 'react-icons/fa';

import { AdminModalProvider } from '@/context/admin-modal-context';

function NavLink({
  href,
  active,
  children,
}: {
  href: string;
  active: boolean | string;
  children: React.ReactNode;
}) {
  return (
    <Link
      href={href}
      className={`${styles.navLink} ${active === true || active === styles.activeLink ? styles.activeLink : ''}`}
    >
      {children}
    </Link>
  );
}

function LayoutContent({ children }: { children: React.ReactNode }) {
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [user, setUser] = useState<{ email: string } | null>(null);

  const router = useRouter();
  const pathname = usePathname();

  // Səhifə Başlıqları
  const getPageTitle = () => {
    if (pathname === '/admin') return 'Dashboard';
    if (pathname.includes('products')) return 'Products';
    if (pathname.includes('categories')) return 'Categories';
    if (pathname.includes('colors')) return 'Colors';
    if (pathname.includes('designers')) return 'Designers';
    if (pathname.includes('collections')) return 'Collections';
    if (pathname.includes('contact')) return 'Inbox';
    if (pathname.includes('rooms')) return 'Rooms';
    if (pathname.includes('materials')) return 'Materials';
    // if (pathname.includes('tags')) return 'Tags';
    if (pathname.includes('change-password')) return 'Security';
    return 'Admin';
  };

  // Logout Funksiyası
  const handleLogout = async () => {
    try {
      // Backend-ə logout sorğusu (varsa)
      await fetch('/api/admin/logout', { method: 'POST' });
    } catch (e) {
      console.error(e);
    } finally {
      // 1. LocalStorage təmizlə
      localStorage.clear();

      // 2. Cookieləri təmizlə
      document.cookie.split(";").forEach((c) => {
        document.cookie = c.replace(/^ +/, "").replace(/=.*/, "=;expires=" + new Date().toUTCString() + ";path=/");
      });

      // 3. Logina at
      router.push('/login');
    }
  };

  // Admin body attribute - böyük ekranlarda ortalanmanı ləğv etmək üçün
  useEffect(() => {
    document.body.setAttribute('data-admin', 'true');
    document.documentElement.setAttribute('data-admin', 'true');
    return () => {
      document.body.removeAttribute('data-admin');
      document.documentElement.removeAttribute('data-admin');
    };
  }, []);

  // Resize Handler
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 1024) setIsSidebarOpen(false);
      else setIsSidebarOpen(true);
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // User Load
  useEffect(() => {
    const storedUser = localStorage.getItem('user');
    if (storedUser) {
      try {
        setUser(JSON.parse(storedUser));
      } catch {
        localStorage.removeItem('user');
      }
    }
  }, []);

  // User Load

  useEffect(() => {
    const token = document.cookie.includes('accessToken') || localStorage.getItem('user');
    if (!token) router.push('/login');
  }, [router]);

  const isActive = (path: string) => pathname === path || pathname.startsWith(path + '/') ? styles.activeLink : '';

  return (
    <div className={styles.adminLayout}>

      {/* SIDEBAR */}
      <aside className={`${styles.sidebar} ${isSidebarOpen ? styles.sidebarOpen : ''}`}>

        {/* LOGO */}
        <div className={styles.sidebarHeader}>
          <Link href="/admin" className={styles.logo} style={{ textDecoration: 'none' }}>
            <div style={{
              background: '#111',
              padding: '6px 12px',
              borderRadius: '10px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              marginLeft: '-12px'
            }}>
              <Image
                src="/images/logo/svlogosparro.svg"
                alt="Sparro Logo"
                width={100}
                height={24}
                style={{ objectFit: 'contain' }}
                priority
              />
            </div>
          </Link>

          <button
            className={styles.menuButton}
            onClick={() => setIsSidebarOpen(false)}
            style={{ marginLeft: 'auto' }}
          >
            ×
          </button>
        </div>

        <nav className={styles.sidebarNav} style={{ paddingTop: '20px' }}>

          <NavLink href="/admin" active={pathname === '/admin'}>
            <FaHome /> Dashboard
          </NavLink>
          <NavLink href="/admin/products" active={isActive('/admin/products')}>
            <FaBox /> Products
          </NavLink>
          <NavLink href="/admin/categories" active={isActive('/admin/categories')}>
            <FaTags /> Categories
          </NavLink>
          <NavLink href="/admin/collections" active={isActive('/admin/collections')}>
            <FaFolder /> Collections
          </NavLink>
          <NavLink href="/admin/designers" active={isActive('/admin/designers')}>
            <FaPaintBrush /> Designers
          </NavLink>
          <NavLink href="/admin/colors" active={isActive('/admin/colors')}>
            <FaPalette /> Colors
          </NavLink>
          <NavLink href="/admin/materials" active={isActive('/admin/materials')}>
            <FaCube /> Materials
          </NavLink>
          <NavLink href="/admin/rooms" active={isActive('/admin/rooms')}>
            <FaBuilding /> Rooms
          </NavLink>
          <NavLink href="/admin/contact" active={isActive('/admin/contact')}>
            <FaEnvelope /> Messages
          </NavLink>
          <NavLink href="/admin/change-password" active={isActive('/admin/change-password')}>
            <FaLock /> Security
          </NavLink>
        </nav>

        {/* SIDEBAR FOOTER */}
        <div className={styles.sidebarFooter}>
          {user && (
            <div className={styles.userProfile}>
              <div className={styles.userAvatar}>
                <Image
                  src="/images/admin/admin-profile.png"
                  alt="Admin"
                  width={38}
                  height={38}
                  style={{ objectFit: 'cover', width: '100%', height: '100%' }}
                />
              </div>
              <div className={styles.userInfo}>
                <span className={styles.userName}>Admin</span>
                <span className={styles.userEmail} title={user.email}>
                  {user.email}
                </span>
              </div>
            </div>
          )}
          <button onClick={handleLogout} className={styles.logoutButton}>
            <FaSignOutAlt /> Log Out
          </button>
        </div>
      </aside>

      {/* MAIN CONTENT */}
      <div className={styles.mainContent}>

        <header className={styles.header}>
          <div className={styles.headerLeft}>
            <button className={styles.menuButton} onClick={() => setIsSidebarOpen(true)}>
              <FaBars />
            </button>
            <h2 className={styles.pageTitle}>{getPageTitle()}</h2>
          </div>
          <div className={styles.headerRight}>
            <div className={styles.adminAvatar}>
              <Image
                src="/images/admin/admin-profile.png"
                alt="Admin"
                width={40}
                height={40}
                style={{ objectFit: 'cover', width: '100%', height: '100%' }}
                priority
              />
            </div>
            <span className={styles.adminLabel}>Admin</span>
          </div>
        </header>

        <main className={styles.content}>
          {children}
        </main>
      </div>
    </div>
  );
}

import SessionKeepAlive from './components/SessionKeepAlive';

// --- ƏSAS LAYOUT (Wrapper) ---
export default function AdminLayout({ children }: { children: React.ReactNode }) {
  return (
