// --- PROPS INTERFACE ---
interface HomeContentProps {
  products: FrontendProduct[]; // Serverdən gələn məhsullar
  collections: BackendCollection[]; // Serverdən gələn kolleksiyalar
}

import { BackendCollection } from "@/lib/collections";

import paletteData from "@/mock/palette/home-palette/index.json";

import homeBannerData from "@/mock/middle-banner/home-middle/index.json";
import homeVideoData from "@/mock/home-video/index.json";

// --- PALETTE TYPES ---
interface PaletteProps {
  title: string;
  description: string;
  buttonText: string;
  buttonLink: string;
  imageUrl: string;
  backgroundColor: string;
  imageSize?: "normal" | "large" | "custom";
}

interface PaletteData {
  id: string;
  componentType: "PaletteRightImage" | "PaletteLeftImage";
  props: PaletteProps;
}

// === MAIN COMPONENT ===
const HomeContent = ({ products, collections }: HomeContentProps) => {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const homePalettes = paletteData.homePage as PaletteData[];

  const renderPalette = (palette: PaletteData) => {
    if (palette.componentType === "PaletteRightImage") {
      return <PaletteRightImage key={palette.id} {...palette.props} />;
    } else if (palette.componentType === "PaletteLeftImage") {
      return <PaletteLeftImage key={palette.id} {...palette.props} />;
    }
    return null;
  };

  return (
    <>
      <HeroSection />
      <div id="header-trigger" style={{ height: 1 }} />

      {/* Product Slider hələlik statik qalır */}
      <ProductSlider />

      {/* Palette 1 */}
      {mounted &&
        homePalettes.find((p) => p.id === "homePaletteRight1") &&
        renderPalette(homePalettes.find((p) => p.id === "homePaletteRight1")!)}

      <NewsSection limit={4} collections={collections} />

      {/* --- DİNAMİK PRODUCT NEWS SLIDER --- */}
      {/* Serverdən gələn 'products' propunu bura ötürürük */}
      <ProductNewsSlider products={products} />

      <div className="hideOnMobile">
        {/* @ts-ignore */}
        <MiddleBanner {...homeBannerData.homePage[0].props} />
      </div>
      <div className="showOnlyOnMobile">
        <HomeVideo
          variant="mobile"
          imageUrl={homeVideoData.homePage.mobileVideo.imageUrl}
        />
      </div>

      <TrustBadges />

      {/* Palette 2 */}
      {mounted &&
        homePalettes.find((p) => p.id === "homePaletteRight2") &&
        renderPalette(homePalettes.find((p) => p.id === "homePaletteRight2")!)}

      {/* @ts-ignore */}
      {/* <MiddleBanner {...homeBannerData.homePage[1].props} /> */}

      {/* Palette Left 1 */}
      {mounted &&
        homePalettes.find((p) => p.id === "homePaletteLeft1") &&
        renderPalette(homePalettes.find((p) => p.id === "homePaletteLeft1")!)}

      <div className="hideOnMobile">
        <HomeVideo imageUrl={homeVideoData.homePage.defaultVideo.imageUrl} />
      </div>

      {/* Palette 3 */}
      {mounted &&
        homePalettes.find((p) => p.id === "homePaletteRight3") &&
        renderPalette(homePalettes.find((p) => p.id === "homePaletteRight3")!)}

      <Form />
    </>
  );
};

export default HomeContent;

import React from 'react';
import { componentMap, ComponentName } from '@/component-map';

interface PageComponent {
  component: string;
  props: Record<string, any>;
}

interface PageBuilderProps {
  components: PageComponent[];
}

const PageBuilder: React.FC<PageBuilderProps> = ({ components }) => {
  if (!components || !Array.isArray(components)) {
    return null;
  }

  return (
    <>
      {components.map((block, index) => {
        const componentName = block.component as ComponentName;
        const Component = componentMap[componentName] as React.ComponentType<any>;
        if (!Component) {
          if (process.env.NODE_ENV === 'development') {
            console.warn(`Diqqət: "${block.component}" adlı komponent tapılmadı.`);
          }
          return null;
        }
        return <Component key={`${block.component}-${index}`} {...block.props} />;
      })}
    </>
  );
};

export default PageBuilder;

