const BASE_URL = process.env.NEXT_PUBLIC_API_URL || 'https://furniture.elforduniversity.com';

interface ApiOptions extends RequestInit {
  data?: any;
  token?: string;
  headers?: Record<string, string>;
}

// ------------------------------------------------------------------
// REFRESH MUTEX (Bir neçə sorğu eyni anda 401 alsa 1 dəfə yenilənəcək)
// ------------------------------------------------------------------
let refreshPromise: Promise<string | null> | null = null;

async function doRefresh(): Promise<string | null> {
  if (typeof window === 'undefined') return null;

  // Əgər artıq arxa planda refresh call gedirsə, onu gözlə
  if (refreshPromise) {
    console.log('[api-client] Refresh artiq gedir, mutex gözləyir...');
    return refreshPromise;
  }

  refreshPromise = (async () => {
    try {
      console.log('[api-client] /api/admin/refresh proksi çağırılır...');
      const currentToken = localStorage.getItem('accessToken');

      const res = await fetch('/api/admin/refresh', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(currentToken ? { 'Authorization': `Bearer ${currentToken}` } : {})
        },
        credentials: 'include'
      });

      if (!res.ok) {
        console.warn('[api-client] Proxy refresh uğursuz, status:', res.status);
        return null;
      }

      const data = await res.json();
      if (data.accessToken) {
        // Tokeni localStorage və cookie-yə yaz (Frontend və Middleware üçün)
        localStorage.setItem('accessToken', data.accessToken);
        document.cookie = `accessToken=${data.accessToken}; path=/; max-age=${60 * 60 * 24}; SameSite=Strict`;
        console.log('[api-client] ✅ Token uğurla yeniləndi');
        return data.accessToken;
      }
      return null;
    } catch (err) {
      console.error('[api-client] Refresh Xətası:', err);
      return null;
    } finally {
      // Kilidi açırıq ki, gələcəkdə yenidən lazım olsa işləsin
      refreshPromise = null;
    }
  })();

  return refreshPromise;
}

// ------------------------------------------------------------------
// ƏSAS API REQUEST FUNKSİYASI
// ------------------------------------------------------------------
export async function apiRequest<T>(
  endpoint: string,
  options: ApiOptions = {},
  retryCount = 0
): Promise<T> {
  // Avtomatik token tapırıq (əgər ötürülməyibsə)
  let currentToken = options.token;
  if (!currentToken && typeof window !== 'undefined') {
    currentToken = localStorage.getItem('accessToken') || undefined;
  }

  const { data, token, headers, ...customConfig } = options;

  const config: RequestInit = {
    method: options.method || 'GET',
    headers: {
      'Content-Type': 'application/json',
      ...(currentToken && { Authorization: `Bearer ${currentToken}` }),
      ...(headers || {}),
    },
    cache: options.cache,
    ...customConfig,
  };

  if (data) {
    if (data instanceof FormData) {
      config.body = data;
      delete (config.headers as Record<string, string>)['Content-Type'];
    } else {
      config.body = JSON.stringify(data);
    }
  }

  const url = `${BASE_URL}${endpoint.startsWith('/') ? endpoint : `/${endpoint}`}`;

  try {
    const response = await fetch(url, config);

    // 1. Rate Limit gələrsə (429)
    if (response.status === 429 && retryCount < 3) {
      const waitTime = 2000 * Math.pow(2, retryCount);
      console.warn(`[api-client] Rate limit (429), ${waitTime}ms gözlənilir...`);
      await new Promise((r) => setTimeout(r, waitTime));
      return apiRequest<T>(endpoint, options, retryCount + 1);
    }

    // 2. Token Expired gələrsə (401)
    if (response.status === 401 && currentToken) {
      if (endpoint.toLowerCase().includes('logout')) {
        console.warn(`[api-client] 401 from ${endpoint}, skipping refresh logic to avoid infinite loops.`);
        const err: any = new Error('Sessiya onsuz da bitmişdir.');
        err.status = 401;
        throw err;
      }

      if (retryCount >= 1) {
        // Artıq refresh edilib və yenə 401 gəlirsə -> Logout
        console.error('[api-client] Refresh sonrası yenə 401. Sessiya bitdi.');

        // Error atırıq, lakin UI-da Catch edib çıxmaq da olar
        const err: any = new Error('Sessiya tamamilə bitdi. Yenidən daxil olun.');
        err.status = 401;
        throw err;
      }

      console.warn(`[api-client] 401 Unauthorized (${endpoint}). Refresh cəhd edilir...`);
      const newAccessToken = await doRefresh();

      if (newAccessToken) {
        // Uğurlu refresh: orijinal sorğunu yeni tokenlə TƏKRARLA
        console.log(`[api-client] Orijinal sorğu yeni tokenlə təkrarlanır: ${endpoint}`);
        return apiRequest<T>(endpoint, { ...options, token: newAccessToken }, retryCount + 1);
      } else {
        // Refresh uğursuz: İstifadəçi loginə qayıtmalıdır
        const err: any = new Error('Sessiya yenilənmədi. Zəhmət olmasa yenidən daxil olun.');
        err.status = 401;
        throw err;
      }
    }

    // 401 amma token heç vaxt olmayıbsa (məsələn public api)
    if (response.status === 401) {
      const err: any = new Error('İcazəniz yoxdur.');
      err.status = 401;
      throw err;
    }

    // 3. Digər xətalar
    if (!response.ok) {
      if (response.status === 204) return {} as T;
      let errorMessage = `API xəta (${response.status})`;
      try {
        const rawText = await response.text();
        if (rawText) {
          try {
            const errorData = JSON.parse(rawText);
            errorMessage = errorData.message ?? errorData.detail ?? errorData.title ?? rawText.slice(0, 200);
          } catch {
            errorMessage = rawText.slice(0, 200);
          }
        }
      } catch { }
      const error: any = new Error(errorMessage);
      error.status = response.status;
      throw error;
    }

    // 4. Uğurlu cavab
    if (response.status === 204) return {} as T;
    const text = await response.text();
    if (!text) return {} as T;
    try {
      return JSON.parse(text) as T;
    } catch {
      return { message: text } as any;
    }

  } catch (error) {
    if (!(error instanceof Error) || !error.message.includes('Sessiya')) {
      console.error(`[api-client] Request Failed (${endpoint}):`, error);
    }
    throw error;
  }
}

// src/lib/auth.ts
import { apiRequest } from './api-client';

// --- TİPLƏR (INTERFACES) ---

export interface User {
  id: string;
  email: string;
  firstName?: string;
  lastName?: string;
  roles?: string[];
}

export interface LoginResponse {
  accessToken: string;
  refreshToken?: string;
  user?: User;
  expiration?: string;
}

export interface ChangePasswordPayload {
  currentPassword: string;
  newPassword: string;
  confirmNewPassword: string;
}

// Tokeni oxumaq üçün köməkçi funksiya (Sənin kodun)
function decodeJWT(token: string): any {
  try {
    const tokenParts = token.split('.');
    if (tokenParts.length !== 3) return null;
    
    let payload = tokenParts[1];
    
    // Base64Url -> Base64
    payload = payload.replace(/-/g, '+').replace(/_/g, '/');
    
    // Padding əlavə etmək (atob xəta verməsin deyə)
    const padding = payload.length % 4;
    if (padding > 0) {
      payload += '='.repeat(4 - padding);
    }

    const decoded = typeof window !== 'undefined' 
      ? decodeURIComponent(escape(atob(payload))) // UTF-8 dəstəyi üçün
      : Buffer.from(payload, 'base64').toString('utf-8');
      
    return JSON.parse(decoded);
  } catch (e) {
    console.error('[auth] decodeJWT xətası:', e);
    return null;
  }
}

/** JWT-nin bitmə vaxtını millisaniyə qaytarır (Date.now() ilə müqayisə üçün) */
export function getTokenExpiryMs(accessToken: string): number | null {
  const payload = decodeJWT(accessToken);
  if (!payload || typeof payload.exp !== 'number') return null;
  return payload.exp * 1000;
}

// ================= API METODLARI =================

// --- 1. LOGIN USER ---
export async function loginUser(username: string, password: string): Promise<LoginResponse> {
  console.log("📡 Login sorğusu göndərilir: /api/Account/login");

  const response: any = await apiRequest('/api/Account/login', {
    method: 'POST',
    data: {
      username: username, 
      password: password  
    }
  });

  const accessToken = response.accessToken ?? response.AccessToken ?? (typeof response === 'string' ? response : null);

  if (!accessToken) {
     console.error("❌ Token tapılmadı. Cavab:", response);
     throw new Error("Login uğursuz oldu. Token gəlmədi.");
  }

  // User məlumatlarını tokendən oxuma
  let user: User = { id: '0', email: username };
  
  try {
    const payload = decodeJWT(accessToken);
    if (payload) {
      const emailFromToken = payload['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name'] 
                           || payload.email 
                           || payload.sub 
                           || username;
      user = {
        id: payload.jti || payload.sub || '0',
        email: emailFromToken,
        roles: payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] || []
      };
    }
  } catch (e) {
    console.warn("⚠️ Token decode edilə bilmədi:", e);
  }

  return {
    accessToken: accessToken,
    refreshToken: response.refreshToken ?? response.RefreshToken ?? '', 
    user: user,
    expiration: response.expiration
  };
}

// --- 2. CHANGE PASSWORD ---
export async function changePassword(payload: ChangePasswordPayload, token: string) {
  return apiRequest('/api/Account/change-password', {
    method: 'POST',
    data: {
      CurrentPassword: payload.currentPassword,
      NewPassword: payload.newPassword,
      ConfirmPassword: payload.confirmNewPassword,
    },
    token: token
  });
}

// --- 3. LOGOUT ---
export async function logoutUser(accessToken: string) {
  try {
    await apiRequest<void>('/api/Account/logout', { 
       method: 'POST',
       token: accessToken,
    });
  } catch (e) {
    console.log("Logout API xətası (kritik deyil):", e);
  }

  // 2. Brauzerdən təmizləyirik
  logout();
}

// ================= KÖMƏKÇİ FUNKSİYALAR (HELPERS) =================

export function logout() {
    if (typeof window === 'undefined') return;
    
    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');
    localStorage.removeItem('user');
    
    // Bütün cookieləri sıfırlayırıq
    document.cookie.split(";").forEach((c) => {
      document.cookie = c.replace(/^ +/, "").replace(/=.*/, "=;expires=" + new Date().toUTCString() + ";path=/");
    });

    window.location.href = '/login';
}

export function setTokens(accessToken: string, refreshToken: string): void {
    if (typeof window === 'undefined') return;
    localStorage.setItem('accessToken', accessToken);
    if(refreshToken) localStorage.setItem('refreshToken', refreshToken);
}

export function getAccessToken() {
  if (typeof window !== 'undefined') return localStorage.getItem('accessToken');
  return null;
}

export function getRefreshToken() {
  if (typeof window !== 'undefined') return localStorage.getItem('refreshToken');
  return null;
}

